css:
:root{
  --ink:#111111; --charcoal:#2B2B2B; --sand:#D6C6B2; --gold:#D4AF37; --rose:#C58C8C;
  --ivory:#F7F4EF; --ivory-d:#EFEAE1; --line:#E2DACE; --line-d:rgba(255,255,255,.14);
  --muted:#6F6A64; --muted-d:rgba(247,244,239,.62); --white:#FFFFFF;
  --gut:46px; --r:2px;
  --shadow:0 1px 2px rgba(17,17,17,.04), 0 14px 36px rgba(17,17,17,.08);
  --shadow-lg:0 2px 8px rgba(17,17,17,.06), 0 32px 74px rgba(17,17,17,.16);
  --serif:"Playfair Display",Georgia,"Times New Roman",serif;
  --sans:Montserrat,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --script:"Great Vibes",cursive;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--ivory);color:var(--ink);font-family:var(--sans);
  font-size:15.5px;line-height:1.8;font-weight:400;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--serif);font-weight:400;line-height:1.16;margin:0;letter-spacing:.005em}
p{margin:0}
a{color:inherit;text-decoration:none}
img{max-width:100%}
ul,ol{margin:0;padding:0;list-style:none}

.wrap{width:100%;max-width:1320px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:104px;padding-bottom:104px}
.sec-t{padding-top:76px;padding-bottom:76px}
.lbl{font-family:var(--sans);font-weight:600;font-size:10.5px;letter-spacing:.26em;
  text-transform:uppercase;color:var(--muted);display:block;margin-bottom:18px}
.lbl-g{color:var(--gold)}
.scr{font-family:var(--script);font-size:1.5em;color:var(--gold);line-height:.9;
  display:inline-block;vertical-align:baseline}
.h2{font-size:clamp(30px,3.9vw,50px)}
.lead{color:var(--muted);font-size:15.8px;max-width:60ch;line-height:1.9}
.ctr{text-align:center}
.ctr .lead{margin-left:auto;margin-right:auto}
.sec-head{margin-bottom:48px}
.rule-g{width:52px;height:1px;background:var(--gold);margin-bottom:22px;display:block}
.ctr .rule-g{margin-left:auto;margin-right:auto}

/* ---------- images ---------- */
.cimg{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;background:var(--ivory-d)}
.pimg{display:block;width:100%;height:auto;aspect-ratio:4/5;object-fit:cover;background:var(--ivory-d)}

/* ---------- reveal (pure CSS, JS-free) ---------- */
.rv{animation:rvIn .9s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:.55;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  font-family:var(--sans);font-weight:600;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;
  padding:18px 34px;border-radius:var(--r);border:1px solid transparent;cursor:pointer;
  transition:background .22s ease,color .22s ease,border-color .22s ease;white-space:nowrap}
.btn-1{background:var(--ink);color:var(--ivory)}
.btn-1:hover{background:var(--charcoal)}
.btn-g{background:var(--gold);color:var(--ink)}
.btn-g:hover{background:#C39F2C}
.btn-2{background:transparent;color:var(--ink);border-color:var(--sand)}
.btn-2:hover{border-color:var(--ink);background:var(--ivory-d)}
.btn-w{background:var(--ivory);color:var(--ink);border-color:var(--ivory)}
.btn-w:hover{background:#fff}
.btn-o{background:transparent;color:var(--ivory);border-color:rgba(247,244,239,.42)}
.btn-o:hover{background:rgba(247,244,239,.12);border-color:var(--ivory)}
.btn-sm{padding:13px 22px;font-size:9.5px}
.btn-lg{padding:20px 42px;font-size:11px}
.lnk{font-family:var(--sans);font-weight:600;font-size:9.5px;letter-spacing:.2em;
  text-transform:uppercase;color:var(--ink);display:inline-flex;align-items:center;gap:9px}
.lnk::after{content:"";width:20px;height:1px;background:var(--gold);transition:width .22s ease}
a:hover .lnk::after{width:34px}
.lnk-w{color:var(--ivory)}

/* ---------- header ---------- */
header{position:sticky;top:0;z-index:60;background:rgba(247,244,239,.96);
  backdrop-filter:saturate(140%) blur(12px);border-bottom:1px solid var(--line)}
.hdr{display:flex;align-items:center;gap:24px;min-height:84px}
.brand{flex-shrink:0;line-height:1;white-space:nowrap;display:flex;flex-direction:column;
  align-items:center;gap:1px}
.brand .b1,.brand .b3{font-family:var(--serif);font-weight:400;font-size:15px;letter-spacing:.34em;
  text-transform:uppercase;color:var(--ink)}
.brand .b2{font-family:var(--script);font-size:19px;color:var(--gold);line-height:.7;margin:-2px 0}
.nav{margin-left:auto;display:flex;align-items:center;gap:2px}
.nav>li{position:relative}
.nav a.top,.nav .drop-lbl{display:flex;align-items:center;gap:7px;padding:10px 12px;
  font-family:var(--sans);font-weight:600;font-size:10px;letter-spacing:.17em;text-transform:uppercase;
  color:var(--ink);cursor:pointer;white-space:nowrap;transition:color .2s ease}
.nav a.top:hover,.nav .drop-lbl:hover{color:var(--gold)}
.nav-cta{display:none}
.nav .caret{width:8px;height:8px;flex-shrink:0;opacity:.5}
.menu{position:absolute;top:calc(100% + 16px);left:-10px;min-width:272px;background:var(--white);
  border:1px solid var(--line);box-shadow:var(--shadow-lg);padding:16px 10px;
  opacity:0;visibility:hidden;transform:translateY(8px);transition:.2s ease}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:10px 16px;font-family:var(--serif);font-size:15px;color:var(--ink);
  transition:.18s ease}
.menu a:hover{background:var(--ivory-d);color:var(--gold)}
.menu .mh{display:block;padding:4px 16px 10px;font-size:9.5px;font-weight:600;letter-spacing:.24em;
  text-transform:uppercase;color:var(--sand)}
.hdr-act{display:flex;align-items:center;flex-shrink:0}
.burger,.mtoggle,.dtoggle{display:none}

/* ---------- hero (dark, cinematic) ---------- */
.hero{position:relative;overflow:hidden;background:var(--ink)}
.hero-bg{position:absolute;inset:0;z-index:0}
.hero-bg img{width:100%;height:100%;object-fit:cover;object-position:58% 44%}
.hero-scrim{position:absolute;inset:0;z-index:1;pointer-events:none;
  background:linear-gradient(98deg,rgba(17,17,17,.92) 0%,rgba(17,17,17,.80) 30%,
    rgba(17,17,17,.44) 56%,rgba(17,17,17,.20) 78%,rgba(17,17,17,.12) 100%)}
.hero-grid{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.02fr) minmax(0,.98fr);
  gap:56px;align-items:center;padding-top:104px;padding-bottom:104px}
.hero-txt{color:var(--ivory);min-width:0}
.hero-txt .lbl{color:var(--gold)}
h1{font-size:clamp(36px,4.9vw,62px);color:var(--ivory);margin-bottom:22px;line-height:1.1;font-weight:400}
h1 .scr{font-size:1.15em;color:var(--gold)}
.hero-lead{font-size:16px;color:rgba(247,244,239,.82);max-width:48ch;margin-bottom:32px;line-height:1.9}
.ticks{display:flex;flex-wrap:wrap;gap:12px 26px;margin-top:28px}
.tick{display:flex;align-items:center;gap:9px;font-size:11px;font-weight:600;letter-spacing:.14em;
  text-transform:uppercase;color:rgba(247,244,239,.72)}
.tick svg{width:14px;height:14px;flex-shrink:0}
.swap-tag{position:absolute;right:14px;bottom:14px;z-index:3;background:rgba(17,17,17,.7);
  color:var(--ivory);font-size:9px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;
  padding:7px 14px}

/* ---------- brief form ---------- */
.qs{background:var(--ivory);border:1px solid var(--line);box-shadow:var(--shadow-lg);
  padding:38px 36px;min-width:0}
.qs-head{padding-bottom:22px;border-bottom:1px solid var(--line);margin-bottom:26px}
.qs-head h2{font-size:27px;margin-bottom:8px}
.qs-head p{font-size:13.6px;color:var(--muted);line-height:1.7}
.stp{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.stepper{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin-bottom:28px}
.stepper label{display:flex;align-items:center;gap:8px;min-width:0;cursor:pointer;padding-top:13px;
  border-top:2px solid var(--line);transition:border-color .25s ease}
.stepper b{font-family:var(--serif);font-weight:400;font-size:13px;color:var(--muted);flex-shrink:0;
  transition:color .25s ease}
.stepper span{font-size:9px;font-weight:600;letter-spacing:.13em;text-transform:uppercase;
  color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .25s ease}
.pane{display:none;gap:18px}
#rq1:checked ~ .panes .p1,#rq2:checked ~ .panes .p2,
#rq3:checked ~ .panes .p3,#rq4:checked ~ .panes .p4{display:grid}
#rq1:checked ~ .stepper label:nth-child(1),#rq2:checked ~ .stepper label:nth-child(2),
#rq3:checked ~ .stepper label:nth-child(3),#rq4:checked ~ .stepper label:nth-child(4){border-top-color:var(--gold)}
#rq1:checked ~ .stepper label:nth-child(1) b,#rq1:checked ~ .stepper label:nth-child(1) span,
#rq2:checked ~ .stepper label:nth-child(2) b,#rq2:checked ~ .stepper label:nth-child(2) span,
#rq3:checked ~ .stepper label:nth-child(3) b,#rq3:checked ~ .stepper label:nth-child(3) span,
#rq4:checked ~ .stepper label:nth-child(4) b,#rq4:checked ~ .stepper label:nth-child(4) span{color:var(--ink)}
.field{min-width:0}
.field>label{display:block;font-size:9.5px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;
  color:var(--muted);margin-bottom:9px}
input,select,textarea{min-width:0;width:100%;border:1px solid var(--line);border-radius:var(--r);
  padding:14px 15px;font-size:14.5px;font-family:var(--sans);color:var(--ink);background:var(--white);
  appearance:none;transition:border-color .2s ease,box-shadow .2s ease}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--gold);
  box-shadow:0 0 0 3px rgba(212,175,55,.24)}
select{background-image:linear-gradient(45deg,transparent 50%,var(--muted) 50%),
  linear-gradient(135deg,var(--muted) 50%,transparent 50%);
  background-position:calc(100% - 20px) 21px,calc(100% - 14px) 21px;
  background-size:6px 6px,6px 6px;background-repeat:no-repeat;padding-right:42px}
textarea{resize:vertical;min-height:94px;line-height:1.6}
input::placeholder,textarea::placeholder{color:#A9A29A;font-size:13.5px}
input[type=file]{padding:11px 14px;font-size:12.5px}
.frow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:13px}
.frow>*{min-width:0}
.picks{display:flex;flex-wrap:wrap;gap:8px}
.picks label{display:inline-flex;align-items:center;font-size:11.5px;font-weight:500;letter-spacing:.06em;
  padding:10px 16px;border:1px solid var(--line);background:var(--white);cursor:pointer;transition:.18s ease}
.picks input{position:absolute;opacity:0;width:0;height:0}
.picks label:hover{border-color:var(--sand)}
.picks label:has(input:checked){background:var(--ink);border-color:var(--ink);color:var(--ivory)}
.btnrow{display:flex;gap:12px;flex-wrap:wrap}
.btnrow>*{flex:1 1 0;min-width:0}
.btnrow .btn-2{flex:0 0 auto;padding-left:26px;padding-right:26px}
.nextb{cursor:pointer}
.consent{display:flex;gap:12px;align-items:flex-start;font-size:12.4px;color:var(--muted);
  line-height:1.7;cursor:pointer;min-width:0}
.consent input{width:16px;height:16px;flex-shrink:0;margin-top:3px;accent-color:var(--gold);appearance:auto}
.fnote{font-size:10px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;
  color:var(--sand);line-height:1.9;text-align:center}
.mem{background:var(--charcoal);color:rgba(247,244,239,.66);padding:22px 24px}
.mem .lbl{color:var(--gold);margin-bottom:8px}
.mem h4{font-size:17px;color:var(--ivory);margin-bottom:10px}
.mem p{font-size:12.4px;line-height:1.8}
.opt-lbl{font-size:8.5px;font-weight:600;letter-spacing:.14em;color:var(--gold);
  border:1px solid var(--line);padding:2px 7px;margin-left:7px}

/* ---------- trust strip ---------- */
.strip{background:var(--charcoal);color:rgba(247,244,239,.8)}
.strip .wrap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;
  padding-top:28px;padding-bottom:28px}
.strip div{min-width:0;display:flex;align-items:center;gap:12px;font-size:11.5px;font-weight:500;
  letter-spacing:.1em;text-transform:uppercase}
.strip svg{width:17px;height:17px;flex-shrink:0}

/* ---------- tiles ---------- */
.tiles{display:grid;gap:22px}
.t4{grid-template-columns:repeat(4,minmax(0,1fr))}
.t3{grid-template-columns:repeat(3,minmax(0,1fr))}
.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
.tile{min-width:0;display:block;background:var(--white);border:1px solid var(--line);
  transition:border-color .25s ease,box-shadow .25s ease}
.tile:hover{border-color:var(--sand);box-shadow:var(--shadow)}
.tile .tb{padding:20px 22px 24px}
.tile b{display:block;font-family:var(--serif);font-weight:400;font-size:21px;margin-bottom:7px}
.tile span{display:block;font-size:13.2px;color:var(--muted);line-height:1.75}
.tile .lnk{margin-top:16px}
.kwl{margin-top:12px;font-size:11px;color:var(--sand);line-height:1.8;letter-spacing:.02em}

/* ---------- dark emotional band ---------- */
.dark{background:var(--ink);color:var(--ivory)}
.dark .h2{color:var(--ivory)}
.dark .lead{color:var(--muted-d)}
.band-split{display:grid;grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);gap:0;align-items:center}
.band-txt{padding:96px 60px 96px 0;min-width:0}
.band-txt h2{margin-bottom:22px}
.band-txt p{color:rgba(247,244,239,.72);font-size:16px;line-height:1.95;max-width:50ch;margin-bottom:16px}
.band-img{min-width:0}
.band-img img{display:block;width:100%;height:100%;min-height:440px;object-fit:cover}

/* ---------- gallery (visual proof) ---------- */
.gal{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}
.gal figure{margin:0;min-width:0}
.gal figure:nth-child(3n+2){margin-top:28px}

/* ---------- steps ---------- */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border-top:1px solid var(--line)}
.step{min-width:0;padding:42px 30px 42px 0;border-right:1px solid var(--line);padding-right:30px}
.step:last-child{border-right:0}
.step .n{font-family:var(--serif);font-size:38px;color:var(--sand);display:block;margin-bottom:12px;line-height:1}
.step h3{font-size:21px;margin-bottom:10px}
.step p{font-size:13.6px;color:var(--muted);line-height:1.8}

/* ---------- planning cards ---------- */
.plan{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border:1px solid var(--line);
  background:var(--white)}
.plan a{min-width:0;padding:36px 30px;border-right:1px solid var(--line);transition:background .22s ease}
.plan a:last-child{border-right:0}
.plan a:hover{background:var(--ivory-d)}
.plan h3{font-size:20px;margin-bottom:10px}
.plan p{font-size:13.2px;color:var(--muted);line-height:1.75}
.plan .lnk{margin-top:16px}

/* ---------- locations ---------- */
.loc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:34px}
.loc-col{min-width:0}
.loc-col h3{font-size:20px;margin-bottom:4px}
.loc-col .st{font-size:9.5px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;
  color:var(--sand);display:block;margin-bottom:14px}
.loc-col li{border-bottom:1px solid var(--line)}
.loc-col a{display:block;font-size:13.6px;padding:9px 0;overflow-wrap:anywhere;transition:.18s ease}
.loc-col a:hover{color:var(--gold);padding-left:6px}
.pop{display:flex;flex-wrap:wrap;gap:9px;margin-top:16px}
.pop a{border:1px solid var(--line);padding:9px 17px;font-size:11.5px;font-weight:500;
  background:var(--white);transition:.18s ease}
.pop a:hover{border-color:var(--gold);color:var(--gold)}

/* ---------- faq ---------- */
.faq{max-width:900px;margin:0 auto;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{cursor:pointer;list-style:none;padding:26px 58px 26px 0;position:relative;
  font-family:var(--serif);font-size:21px;transition:color .2s ease}
.faq summary:hover{color:var(--gold)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after,.faq summary::before{content:"";position:absolute;right:12px;top:38px;
  background:var(--gold);transition:transform .25s ease,opacity .25s ease}
.faq summary::after{width:15px;height:1px}
.faq summary::before{width:1px;height:15px;right:19px;top:31px}
.faq details[open] summary::before{opacity:0;transform:rotate(90deg)}
.faq .ans{padding:0 60px 28px 0;font-size:14.8px;color:var(--muted);line-height:1.95}

/* ---------- final CTA ---------- */
.cta-b{position:relative;overflow:hidden;background:var(--ink)}
.cta-img{position:absolute;inset:0;z-index:1}
.cta-img img{width:100%;height:100%;object-fit:cover;opacity:.34}
.cta-in{position:relative;z-index:2;padding:104px 44px;text-align:center}
.cta-in h2{color:var(--ivory);margin-bottom:20px}
.cta-in p{color:rgba(247,244,239,.76);font-size:16.5px;max-width:52ch;margin:0 auto 36px}
.cta-row{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}

/* ---------- footer ---------- */
footer{background:var(--ink);color:rgba(247,244,239,.56);padding-top:84px}
.f-top{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:40px;
  padding-bottom:54px;border-bottom:1px solid var(--line-d)}
.f-brand{min-width:0}
.f-brand .brand{align-items:flex-start;margin-bottom:18px}
.f-brand .brand .b1,.f-brand .brand .b3{color:var(--ivory)}
.f-brand .tag{font-family:var(--serif);font-style:italic;font-size:17px;color:var(--sand);
  display:block;margin-bottom:18px}
.f-brand p{font-size:13.2px;line-height:1.85;max-width:34ch;margin-bottom:22px}
.f-col{min-width:0}
.f-col h3{font-size:9.5px;font-weight:600;letter-spacing:.24em;text-transform:uppercase;
  color:var(--ivory);margin-bottom:18px}
.f-col li{margin-bottom:11px}
.f-col a{font-size:13px;overflow-wrap:anywhere;transition:.18s ease}
.f-col a:hover{color:var(--gold)}
.f-seo{padding:26px 0;border-bottom:1px solid var(--line-d);font-family:var(--serif);
  font-size:17px;color:var(--ivory);text-align:center}
.f-bot{display:flex;flex-wrap:wrap;gap:16px 30px;align-items:center;justify-content:space-between;
  padding:26px 0 32px;font-size:11px;font-weight:500;letter-spacing:.1em;text-transform:uppercase;
  color:rgba(247,244,239,.4)}
.f-bot a:hover{color:var(--gold)}
.credit{display:inline-flex;align-items:center;gap:9px;white-space:nowrap}
.credit img{width:20px;height:20px;border-radius:4px;flex-shrink:0;display:block}
.f-bar{background:var(--rose);color:var(--ink);text-align:center;padding:16px 20px;
  font-size:11px;font-weight:600;letter-spacing:.22em;text-transform:uppercase}
.f-bar .scr{font-size:2em;letter-spacing:0;color:var(--ink);text-transform:none;margin:0 4px}

/* ---------- sticky mobile ---------- */
.sticky{display:none}

/* ---------- thank you ---------- */
.ty{max-width:720px;margin:0 auto;text-align:center}
.ty-mark{width:76px;height:76px;border:1px solid var(--gold);border-radius:50%;display:grid;
  place-items:center;margin:0 auto 30px}
.ty-mark svg{width:32px;height:32px}
.ty h1{color:var(--ink);font-size:clamp(32px,4.4vw,50px);margin-bottom:20px}
.ty>.lead{margin:0 auto 40px}
.ty-next{border-top:1px solid var(--line);text-align:left;margin-bottom:40px}
.ty-next li{display:flex;gap:24px;padding:26px 0;border-bottom:1px solid var(--line);min-width:0}
.ty-next b{font-family:var(--serif);font-size:24px;color:var(--sand);flex-shrink:0;line-height:1.1}
.ty-next span{display:block;min-width:0}
.ty-next strong{display:block;font-family:var(--serif);font-weight:400;font-size:20px;margin-bottom:6px}
.ty-next em{font-style:normal;font-size:14px;color:var(--muted);line-height:1.8}
.note{margin-top:36px;font-size:10.5px;font-weight:500;letter-spacing:.08em;color:var(--muted);
  border:1px dashed var(--sand);padding:16px 22px;line-height:1.9;text-transform:uppercase}

/* ================= responsive ================= */
@media (max-width:1500px){ .nav a.top,.nav .drop-lbl{padding:10px 9px;font-size:9.4px;letter-spacing:.13em}
  .hdr{gap:16px} }
@media (max-width:1280px){
  .burger{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--line);
    background:var(--white);cursor:pointer;margin-left:auto;flex-shrink:0}
  .burger span{display:block;width:20px;height:1px;background:var(--ink);position:relative}
  .burger span::before,.burger span::after{content:"";position:absolute;left:0;width:20px;height:1px;background:var(--ink)}
  .burger span::before{top:-6px}.burger span::after{top:6px}
  .hdr-act{display:none}
  .nav{position:fixed;top:84px;left:0;right:0;bottom:0;margin:0;background:var(--ivory);
    display:block;overflow-y:auto;padding:22px var(--gut) 48px;clip-path:inset(0 0 0 100%);
    pointer-events:none;opacity:0;transition:clip-path .34s ease,opacity .28s ease;z-index:70}
  .mtoggle:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
  .nav>li{border-bottom:1px solid var(--line)}
  .nav a.top,.nav .drop-lbl{padding:18px 2px;font-size:11.5px;letter-spacing:.18em;justify-content:space-between}
  .nav .caret{width:11px;height:11px;transition:transform .22s ease}
  .menu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    padding:0 0 16px;min-width:0;max-height:0;overflow:hidden;transition:max-height .34s ease;background:transparent}
  .dtoggle:checked + .drop-lbl + .menu{max-height:900px}
  .dtoggle:checked + .drop-lbl .caret{transform:rotate(180deg)}
  .menu a{padding:9px 0;font-size:16px;color:var(--muted)}
  .menu .mh{padding-left:0}
  .nav-cta{display:flex!important;flex-direction:column;gap:12px;padding-top:26px;border:0!important}
  .nav-cta .btn{width:100%}
}
@media (max-width:1100px){
  .hero-grid{grid-template-columns:minmax(0,1fr);gap:44px;padding-top:62px;padding-bottom:62px}
  .hero-scrim{background:linear-gradient(180deg,rgba(17,17,17,.72) 0%,rgba(17,17,17,.82) 46%,rgba(17,17,17,.92) 100%)}
  .hero-bg img{object-position:50% 36%}
  .qs{max-width:580px}
  .swap-tag{display:none}
  .t4,.gal{grid-template-columns:repeat(3,minmax(0,1fr))}
  .gal figure:nth-child(3n+2){margin-top:0}
  .t3,.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
  .band-split{grid-template-columns:minmax(0,1fr)}
  .band-txt{padding:66px 0 44px}
  .band-img img{min-height:320px}
  .steps,.plan{grid-template-columns:repeat(2,minmax(0,1fr))}
  .step{border-right:0;border-bottom:1px solid var(--line);padding:34px 0}
  .step:nth-child(odd){border-right:1px solid var(--line);padding-right:28px}
  .step:nth-child(even){padding-left:28px}
  .plan a{border-right:0;border-bottom:1px solid var(--line)}
  .plan a:nth-child(odd){border-right:1px solid var(--line)}
  .loc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
  .strip .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}
  .f-top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .f-brand{grid-column:1/-1}
}
@media (max-width:768px){
  :root{--gut:22px}
  .sec{padding-top:66px;padding-bottom:66px}
  .sec-t{padding-top:52px;padding-bottom:52px}
  .nav{top:74px}
  .hdr{min-height:74px}
  .brand .b1,.brand .b3{font-size:12px;letter-spacing:.28em}
  .brand .b2{font-size:15px}
  .qs{padding:30px 24px}
  .stepper span{display:none}
  .stepper label{justify-content:center;padding-top:11px}
  .cta-in{padding:70px 22px}
  .sticky{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:10px;
    background:rgba(247,244,239,.97);backdrop-filter:blur(12px);border-top:1px solid var(--line);
    padding:11px 14px calc(11px + env(safe-area-inset-bottom))}
  .sticky .btn{flex:1 1 0;min-width:0;padding:15px 8px;font-size:9px;letter-spacing:.1em}
  footer{padding-bottom:78px}
}
@media (max-width:620px){
  .t4,.t3,.t2,.steps,.plan,.loc-grid,.f-top{grid-template-columns:minmax(0,1fr)}
  .gal{grid-template-columns:repeat(2,minmax(0,1fr))}
  .step,.step:nth-child(odd),.step:nth-child(even){border-right:0;padding-left:0;padding-right:0}
  .plan a,.plan a:nth-child(odd){border-right:0}
  .strip .wrap{grid-template-columns:minmax(0,1fr);gap:15px}
  .frow{grid-template-columns:minmax(0,1fr)}
  .f-top{gap:30px}
}
@media (max-width:430px){
  :root{--gut:18px}
  .tile .tb{padding:18px}
  .btn{white-space:normal;text-align:center;padding-left:20px;padding-right:20px;max-width:100%}
  .btnrow{flex-direction:column}
  .btnrow>*{width:100%}
  .faq summary{font-size:18px;padding-right:42px}
}

:root{
  --ink:#111111; --charcoal:#2B2B2B; --sand:#D6C6B2; --gold:#D4AF37; --rose:#C58C8C;
  --ivory:#F7F4EF; --ivory-d:#EFEAE1; --line:#E2DACE; --line-d:rgba(255,255,255,.14);
  --muted:#6F6A64; --muted-d:rgba(247,244,239,.62); --white:#FFFFFF;
  --gut:46px; --r:2px;
  --shadow:0 1px 2px rgba(17,17,17,.04), 0 14px 36px rgba(17,17,17,.08);
  --shadow-lg:0 2px 8px rgba(17,17,17,.06), 0 32px 74px rgba(17,17,17,.16);
  --serif:"Playfair Display",Georgia,"Times New Roman",serif;
  --sans:Montserrat,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --script:"Great Vibes",cursive;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--ivory);color:var(--ink);font-family:var(--sans);
  font-size:15.5px;line-height:1.8;font-weight:400;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--serif);font-weight:400;line-height:1.16;margin:0;letter-spacing:.005em}
p{margin:0}
a{color:inherit;text-decoration:none}
img{max-width:100%}
ul,ol{margin:0;padding:0;list-style:none}

.wrap{width:100%;max-width:1320px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:104px;padding-bottom:104px}
.sec-t{padding-top:76px;padding-bottom:76px}
.lbl{font-family:var(--sans);font-weight:600;font-size:10.5px;letter-spacing:.26em;
  text-transform:uppercase;color:var(--muted);display:block;margin-bottom:18px}
.lbl-g{color:var(--gold)}
.scr{font-family:var(--script);font-size:1.5em;color:var(--gold);line-height:.9;
  display:inline-block;vertical-align:baseline}
.h2{font-size:clamp(30px,3.9vw,50px)}
.lead{color:var(--muted);font-size:15.8px;max-width:60ch;line-height:1.9}
.ctr{text-align:center}
.ctr .lead{margin-left:auto;margin-right:auto}
.sec-head{margin-bottom:48px}
.rule-g{width:52px;height:1px;background:var(--gold);margin-bottom:22px;display:block}
.ctr .rule-g{margin-left:auto;margin-right:auto}

/* ---------- images ---------- */
.cimg{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;background:var(--ivory-d)}
.pimg{display:block;width:100%;height:auto;aspect-ratio:4/5;object-fit:cover;background:var(--ivory-d)}

/* ---------- reveal (pure CSS, JS-free) ---------- */
.rv{animation:rvIn .9s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:.55;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  font-family:var(--sans);font-weight:600;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;
  padding:18px 34px;border-radius:var(--r);border:1px solid transparent;cursor:pointer;
  transition:background .22s ease,color .22s ease,border-color .22s ease;white-space:nowrap}
.btn-1{background:var(--ink);color:var(--ivory)}
.btn-1:hover{background:var(--charcoal)}
.btn-g{background:var(--gold);color:var(--ink)}
.btn-g:hover{background:#C39F2C}
.btn-2{background:transparent;color:var(--ink);border-color:var(--sand)}
.btn-2:hover{border-color:var(--ink);background:var(--ivory-d)}
.btn-w{background:var(--ivory);color:var(--ink);border-color:var(--ivory)}
.btn-w:hover{background:#fff}
.btn-o{background:transparent;color:var(--ivory);border-color:rgba(247,244,239,.42)}
.btn-o:hover{background:rgba(247,244,239,.12);border-color:var(--ivory)}
.btn-sm{padding:13px 22px;font-size:9.5px}
.btn-lg{padding:20px 42px;font-size:11px}
.lnk{font-family:var(--sans);font-weight:600;font-size:9.5px;letter-spacing:.2em;
  text-transform:uppercase;color:var(--ink);display:inline-flex;align-items:center;gap:9px}
.lnk::after{content:"";width:20px;height:1px;background:var(--gold);transition:width .22s ease}
a:hover .lnk::after{width:34px}
.lnk-w{color:var(--ivory)}

/* ---------- header ---------- */
header{position:sticky;top:0;z-index:60;background:rgba(247,244,239,.96);
  backdrop-filter:saturate(140%) blur(12px);border-bottom:1px solid var(--line)}
.hdr{display:flex;align-items:center;gap:24px;min-height:84px}
.brand{flex-shrink:0;line-height:1;white-space:nowrap;display:flex;flex-direction:column;
  align-items:center;gap:1px}
.brand .b1,.brand .b3{font-family:var(--serif);font-weight:400;font-size:15px;letter-spacing:.34em;
  text-transform:uppercase;color:var(--ink)}
.brand .b2{font-family:var(--script);font-size:19px;color:var(--gold);line-height:.7;margin:-2px 0}
.nav{margin-left:auto;display:flex;align-items:center;gap:2px}
.nav>li{position:relative}
.nav a.top,.nav .drop-lbl{display:flex;align-items:center;gap:7px;padding:10px 12px;
  font-family:var(--sans);font-weight:600;font-size:10px;letter-spacing:.17em;text-transform:uppercase;
  color:var(--ink);cursor:pointer;white-space:nowrap;transition:color .2s ease}
.nav a.top:hover,.nav .drop-lbl:hover{color:var(--gold)}
.nav-cta{display:none}
.nav .caret{width:8px;height:8px;flex-shrink:0;opacity:.5}
.menu{position:absolute;top:calc(100% + 16px);left:-10px;min-width:272px;background:var(--white);
  border:1px solid var(--line);box-shadow:var(--shadow-lg);padding:16px 10px;
  opacity:0;visibility:hidden;transform:translateY(8px);transition:.2s ease}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:10px 16px;font-family:var(--serif);font-size:15px;color:var(--ink);
  transition:.18s ease}
.menu a:hover{background:var(--ivory-d);color:var(--gold)}
.menu .mh{display:block;padding:4px 16px 10px;font-size:9.5px;font-weight:600;letter-spacing:.24em;
  text-transform:uppercase;color:var(--sand)}
.hdr-act{display:flex;align-items:center;flex-shrink:0}
.burger,.mtoggle,.dtoggle{display:none}

/* ---------- hero (dark, cinematic) ---------- */
.hero{position:relative;overflow:hidden;background:var(--ink)}
.hero-bg{position:absolute;inset:0;z-index:0}
.hero-bg img{width:100%;height:100%;object-fit:cover;object-position:58% 44%}
.hero-scrim{position:absolute;inset:0;z-index:1;pointer-events:none;
  background:linear-gradient(98deg,rgba(17,17,17,.92) 0%,rgba(17,17,17,.80) 30%,
    rgba(17,17,17,.44) 56%,rgba(17,17,17,.20) 78%,rgba(17,17,17,.12) 100%)}
.hero-grid{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.02fr) minmax(0,.98fr);
  gap:56px;align-items:center;padding-top:104px;padding-bottom:104px}
.hero-txt{color:var(--ivory);min-width:0}
.hero-txt .lbl{color:var(--gold)}
h1{font-size:clamp(36px,4.9vw,62px);color:var(--ivory);margin-bottom:22px;line-height:1.1;font-weight:400}
h1 .scr{font-size:1.15em;color:var(--gold)}
.hero-lead{font-size:16px;color:rgba(247,244,239,.82);max-width:48ch;margin-bottom:32px;line-height:1.9}
.ticks{display:flex;flex-wrap:wrap;gap:12px 26px;margin-top:28px}
.tick{display:flex;align-items:center;gap:9px;font-size:11px;font-weight:600;letter-spacing:.14em;
  text-transform:uppercase;color:rgba(247,244,239,.72)}
.tick svg{width:14px;height:14px;flex-shrink:0}
.swap-tag{position:absolute;right:14px;bottom:14px;z-index:3;background:rgba(17,17,17,.7);
  color:var(--ivory);font-size:9px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;
  padding:7px 14px}

/* ---------- brief form ---------- */
.qs{background:var(--ivory);border:1px solid var(--line);box-shadow:var(--shadow-lg);
  padding:38px 36px;min-width:0}
.qs-head{padding-bottom:22px;border-bottom:1px solid var(--line);margin-bottom:26px}
.qs-head h2{font-size:27px;margin-bottom:8px}
.qs-head p{font-size:13.6px;color:var(--muted);line-height:1.7}
.stp{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.stepper{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin-bottom:28px}
.stepper label{display:flex;align-items:center;gap:8px;min-width:0;cursor:pointer;padding-top:13px;
  border-top:2px solid var(--line);transition:border-color .25s ease}
.stepper b{font-family:var(--serif);font-weight:400;font-size:13px;color:var(--muted);flex-shrink:0;
  transition:color .25s ease}
.stepper span{font-size:9px;font-weight:600;letter-spacing:.13em;text-transform:uppercase;
  color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .25s ease}
.pane{display:none;gap:18px}
#rq1:checked ~ .panes .p1,#rq2:checked ~ .panes .p2,
#rq3:checked ~ .panes .p3,#rq4:checked ~ .panes .p4{display:grid}
#rq1:checked ~ .stepper label:nth-child(1),#rq2:checked ~ .stepper label:nth-child(2),
#rq3:checked ~ .stepper label:nth-child(3),#rq4:checked ~ .stepper label:nth-child(4){border-top-color:var(--gold)}
#rq1:checked ~ .stepper label:nth-child(1) b,#rq1:checked ~ .stepper label:nth-child(1) span,
#rq2:checked ~ .stepper label:nth-child(2) b,#rq2:checked ~ .stepper label:nth-child(2) span,
#rq3:checked ~ .stepper label:nth-child(3) b,#rq3:checked ~ .stepper label:nth-child(3) span,
#rq4:checked ~ .stepper label:nth-child(4) b,#rq4:checked ~ .stepper label:nth-child(4) span{color:var(--ink)}
.field{min-width:0}
.field>label{display:block;font-size:9.5px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;
  color:var(--muted);margin-bottom:9px}
input,select,textarea{min-width:0;width:100%;border:1px solid var(--line);border-radius:var(--r);
  padding:14px 15px;font-size:14.5px;font-family:var(--sans);color:var(--ink);background:var(--white);
  appearance:none;transition:border-color .2s ease,box-shadow .2s ease}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--gold);
  box-shadow:0 0 0 3px rgba(212,175,55,.24)}
select{background-image:linear-gradient(45deg,transparent 50%,var(--muted) 50%),
  linear-gradient(135deg,var(--muted) 50%,transparent 50%);
  background-position:calc(100% - 20px) 21px,calc(100% - 14px) 21px;
  background-size:6px 6px,6px 6px;background-repeat:no-repeat;padding-right:42px}
textarea{resize:vertical;min-height:94px;line-height:1.6}
input::placeholder,textarea::placeholder{color:#A9A29A;font-size:13.5px}
input[type=file]{padding:11px 14px;font-size:12.5px}
.frow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:13px}
.frow>*{min-width:0}
.picks{display:flex;flex-wrap:wrap;gap:8px}
.picks label{display:inline-flex;align-items:center;font-size:11.5px;font-weight:500;letter-spacing:.06em;
  padding:10px 16px;border:1px solid var(--line);background:var(--white);cursor:pointer;transition:.18s ease}
.picks input{position:absolute;opacity:0;width:0;height:0}
.picks label:hover{border-color:var(--sand)}
.picks label:has(input:checked){background:var(--ink);border-color:var(--ink);color:var(--ivory)}
.btnrow{display:flex;gap:12px;flex-wrap:wrap}
.btnrow>*{flex:1 1 0;min-width:0}
.btnrow .btn-2{flex:0 0 auto;padding-left:26px;padding-right:26px}
.nextb{cursor:pointer}
.consent{display:flex;gap:12px;align-items:flex-start;font-size:12.4px;color:var(--muted);
  line-height:1.7;cursor:pointer;min-width:0}
.consent input{width:16px;height:16px;flex-shrink:0;margin-top:3px;accent-color:var(--gold);appearance:auto}
.fnote{font-size:10px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;
  color:var(--sand);line-height:1.9;text-align:center}
.mem{background:var(--charcoal);color:rgba(247,244,239,.66);padding:22px 24px}
.mem .lbl{color:var(--gold);margin-bottom:8px}
.mem h4{font-size:17px;color:var(--ivory);margin-bottom:10px}
.mem p{font-size:12.4px;line-height:1.8}
.opt-lbl{font-size:8.5px;font-weight:600;letter-spacing:.14em;color:var(--gold);
  border:1px solid var(--line);padding:2px 7px;margin-left:7px}

/* ---------- trust strip ---------- */
.strip{background:var(--charcoal);color:rgba(247,244,239,.8)}
.strip .wrap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;
  padding-top:28px;padding-bottom:28px}
.strip div{min-width:0;display:flex;align-items:center;gap:12px;font-size:11.5px;font-weight:500;
  letter-spacing:.1em;text-transform:uppercase}
.strip svg{width:17px;height:17px;flex-shrink:0}

/* ---------- tiles ---------- */
.tiles{display:grid;gap:22px}
.t4{grid-template-columns:repeat(4,minmax(0,1fr))}
.t3{grid-template-columns:repeat(3,minmax(0,1fr))}
.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
.tile{min-width:0;display:block;background:var(--white);border:1px solid var(--line);
  transition:border-color .25s ease,box-shadow .25s ease}
.tile:hover{border-color:var(--sand);box-shadow:var(--shadow)}
.tile .tb{padding:20px 22px 24px}
.tile b{display:block;font-family:var(--serif);font-weight:400;font-size:21px;margin-bottom:7px}
.tile span{display:block;font-size:13.2px;color:var(--muted);line-height:1.75}
.tile .lnk{margin-top:16px}
.kwl{margin-top:12px;font-size:11px;color:var(--sand);line-height:1.8;letter-spacing:.02em}

/* ---------- dark emotional band ---------- */
.dark{background:var(--ink);color:var(--ivory)}
.dark .h2{color:var(--ivory)}
.dark .lead{color:var(--muted-d)}
.band-split{display:grid;grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);gap:0;align-items:center}
.band-txt{padding:96px 60px 96px 0;min-width:0}
.band-txt h2{margin-bottom:22px}
.band-txt p{color:rgba(247,244,239,.72);font-size:16px;line-height:1.95;max-width:50ch;margin-bottom:16px}
.band-img{min-width:0}
.band-img img{display:block;width:100%;height:100%;min-height:440px;object-fit:cover}

/* ---------- gallery (visual proof) ---------- */
.gal{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}
.gal figure{margin:0;min-width:0}
.gal figure:nth-child(3n+2){margin-top:28px}

/* ---------- steps ---------- */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border-top:1px solid var(--line)}
.step{min-width:0;padding:42px 30px 42px 0;border-right:1px solid var(--line);padding-right:30px}
.step:last-child{border-right:0}
.step .n{font-family:var(--serif);font-size:38px;color:var(--sand);display:block;margin-bottom:12px;line-height:1}
.step h3{font-size:21px;margin-bottom:10px}
.step p{font-size:13.6px;color:var(--muted);line-height:1.8}

/* ---------- planning cards ---------- */
.plan{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border:1px solid var(--line);
  background:var(--white)}
.plan a{min-width:0;padding:36px 30px;border-right:1px solid var(--line);transition:background .22s ease}
.plan a:last-child{border-right:0}
.plan a:hover{background:var(--ivory-d)}
.plan h3{font-size:20px;margin-bottom:10px}
.plan p{font-size:13.2px;color:var(--muted);line-height:1.75}
.plan .lnk{margin-top:16px}

/* ---------- locations ---------- */
.loc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:34px}
.loc-col{min-width:0}
.loc-col h3{font-size:20px;margin-bottom:4px}
.loc-col .st{font-size:9.5px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;
  color:var(--sand);display:block;margin-bottom:14px}
.loc-col li{border-bottom:1px solid var(--line)}
.loc-col a{display:block;font-size:13.6px;padding:9px 0;overflow-wrap:anywhere;transition:.18s ease}
.loc-col a:hover{color:var(--gold);padding-left:6px}
.pop{display:flex;flex-wrap:wrap;gap:9px;margin-top:16px}
.pop a{border:1px solid var(--line);padding:9px 17px;font-size:11.5px;font-weight:500;
  background:var(--white);transition:.18s ease}
.pop a:hover{border-color:var(--gold);color:var(--gold)}

/* ---------- faq ---------- */
.faq{max-width:900px;margin:0 auto;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{cursor:pointer;list-style:none;padding:26px 58px 26px 0;position:relative;
  font-family:var(--serif);font-size:21px;transition:color .2s ease}
.faq summary:hover{color:var(--gold)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after,.faq summary::before{content:"";position:absolute;right:12px;top:38px;
  background:var(--gold);transition:transform .25s ease,opacity .25s ease}
.faq summary::after{width:15px;height:1px}
.faq summary::before{width:1px;height:15px;right:19px;top:31px}
.faq details[open] summary::before{opacity:0;transform:rotate(90deg)}
.faq .ans{padding:0 60px 28px 0;font-size:14.8px;color:var(--muted);line-height:1.95}

/* ---------- final CTA ---------- */
.cta-b{position:relative;overflow:hidden;background:var(--ink)}
.cta-img{position:absolute;inset:0;z-index:1}
.cta-img img{width:100%;height:100%;object-fit:cover;opacity:.34}
.cta-in{position:relative;z-index:2;padding:104px 44px;text-align:center}
.cta-in h2{color:var(--ivory);margin-bottom:20px}
.cta-in p{color:rgba(247,244,239,.76);font-size:16.5px;max-width:52ch;margin:0 auto 36px}
.cta-row{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}

/* ---------- footer ---------- */
footer{background:var(--ink);color:rgba(247,244,239,.56);padding-top:84px}
.f-top{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:40px;
  padding-bottom:54px;border-bottom:1px solid var(--line-d)}
.f-brand{min-width:0}
.f-brand .brand{align-items:flex-start;margin-bottom:18px}
.f-brand .brand .b1,.f-brand .brand .b3{color:var(--ivory)}
.f-brand .tag{font-family:var(--serif);font-style:italic;font-size:17px;color:var(--sand);
  display:block;margin-bottom:18px}
.f-brand p{font-size:13.2px;line-height:1.85;max-width:34ch;margin-bottom:22px}
.f-col{min-width:0}
.f-col h3{font-size:9.5px;font-weight:600;letter-spacing:.24em;text-transform:uppercase;
  color:var(--ivory);margin-bottom:18px}
.f-col li{margin-bottom:11px}
.f-col a{font-size:13px;overflow-wrap:anywhere;transition:.18s ease}
.f-col a:hover{color:var(--gold)}
.f-seo{padding:26px 0;border-bottom:1px solid var(--line-d);font-family:var(--serif);
  font-size:17px;color:var(--ivory);text-align:center}
.f-bot{display:flex;flex-wrap:wrap;gap:16px 30px;align-items:center;justify-content:space-between;
  padding:26px 0 32px;font-size:11px;font-weight:500;letter-spacing:.1em;text-transform:uppercase;
  color:rgba(247,244,239,.4)}
.f-bot a:hover{color:var(--gold)}
.credit{display:inline-flex;align-items:center;gap:9px;white-space:nowrap}
.credit img{width:20px;height:20px;border-radius:4px;flex-shrink:0;display:block}
.f-bar{background:var(--rose);color:var(--ink);text-align:center;padding:16px 20px;
  font-size:11px;font-weight:600;letter-spacing:.22em;text-transform:uppercase}
.f-bar .scr{font-size:2em;letter-spacing:0;color:var(--ink);text-transform:none;margin:0 4px}

/* ---------- sticky mobile ---------- */
.sticky{display:none}

/* ---------- thank you ---------- */
.ty{max-width:720px;margin:0 auto;text-align:center}
.ty-mark{width:76px;height:76px;border:1px solid var(--gold);border-radius:50%;display:grid;
  place-items:center;margin:0 auto 30px}
.ty-mark svg{width:32px;height:32px}
.ty h1{color:var(--ink);font-size:clamp(32px,4.4vw,50px);margin-bottom:20px}
.ty>.lead{margin:0 auto 40px}
.ty-next{border-top:1px solid var(--line);text-align:left;margin-bottom:40px}
.ty-next li{display:flex;gap:24px;padding:26px 0;border-bottom:1px solid var(--line);min-width:0}
.ty-next b{font-family:var(--serif);font-size:24px;color:var(--sand);flex-shrink:0;line-height:1.1}
.ty-next span{display:block;min-width:0}
.ty-next strong{display:block;font-family:var(--serif);font-weight:400;font-size:20px;margin-bottom:6px}
.ty-next em{font-style:normal;font-size:14px;color:var(--muted);line-height:1.8}
.note{margin-top:36px;font-size:10.5px;font-weight:500;letter-spacing:.08em;color:var(--muted);
  border:1px dashed var(--sand);padding:16px 22px;line-height:1.9;text-transform:uppercase}

/* ================= responsive ================= */
@media (max-width:1500px){ .nav a.top,.nav .drop-lbl{padding:10px 9px;font-size:9.4px;letter-spacing:.13em}
  .hdr{gap:16px} }
@media (max-width:1280px){
  .burger{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--line);
    background:var(--white);cursor:pointer;margin-left:auto;flex-shrink:0}
  .burger span{display:block;width:20px;height:1px;background:var(--ink);position:relative}
  .burger span::before,.burger span::after{content:"";position:absolute;left:0;width:20px;height:1px;background:var(--ink)}
  .burger span::before{top:-6px}.burger span::after{top:6px}
  .hdr-act{display:none}
  .nav{position:fixed;top:84px;left:0;right:0;bottom:0;margin:0;background:var(--ivory);
    display:block;overflow-y:auto;padding:22px var(--gut) 48px;clip-path:inset(0 0 0 100%);
    pointer-events:none;opacity:0;transition:clip-path .34s ease,opacity .28s ease;z-index:70}
  .mtoggle:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
  .nav>li{border-bottom:1px solid var(--line)}
  .nav a.top,.nav .drop-lbl{padding:18px 2px;font-size:11.5px;letter-spacing:.18em;justify-content:space-between}
  .nav .caret{width:11px;height:11px;transition:transform .22s ease}
  .menu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    padding:0 0 16px;min-width:0;max-height:0;overflow:hidden;transition:max-height .34s ease;background:transparent}
  .dtoggle:checked + .drop-lbl + .menu{max-height:900px}
  .dtoggle:checked + .drop-lbl .caret{transform:rotate(180deg)}
  .menu a{padding:9px 0;font-size:16px;color:var(--muted)}
  .menu .mh{padding-left:0}
  .nav-cta{display:flex!important;flex-direction:column;gap:12px;padding-top:26px;border:0!important}
  .nav-cta .btn{width:100%}
}
@media (max-width:1100px){
  .hero-grid{grid-template-columns:minmax(0,1fr);gap:44px;padding-top:62px;padding-bottom:62px}
  .hero-scrim{background:linear-gradient(180deg,rgba(17,17,17,.72) 0%,rgba(17,17,17,.82) 46%,rgba(17,17,17,.92) 100%)}
  .hero-bg img{object-position:50% 36%}
  .qs{max-width:580px}
  .swap-tag{display:none}
  .t4,.gal{grid-template-columns:repeat(3,minmax(0,1fr))}
  .gal figure:nth-child(3n+2){margin-top:0}
  .t3,.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
  .band-split{grid-template-columns:minmax(0,1fr)}
  .band-txt{padding:66px 0 44px}
  .band-img img{min-height:320px}
  .steps,.plan{grid-template-columns:repeat(2,minmax(0,1fr))}
  .step{border-right:0;border-bottom:1px solid var(--line);padding:34px 0}
  .step:nth-child(odd){border-right:1px solid var(--line);padding-right:28px}
  .step:nth-child(even){padding-left:28px}
  .plan a{border-right:0;border-bottom:1px solid var(--line)}
  .plan a:nth-child(odd){border-right:1px solid var(--line)}
  .loc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
  .strip .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}
  .f-top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .f-brand{grid-column:1/-1}
}
@media (max-width:768px){
  :root{--gut:22px}
  .sec{padding-top:66px;padding-bottom:66px}
  .sec-t{padding-top:52px;padding-bottom:52px}
  .nav{top:74px}
  .hdr{min-height:74px}
  .brand .b1,.brand .b3{font-size:12px;letter-spacing:.28em}
  .brand .b2{font-size:15px}
  .qs{padding:30px 24px}
  .stepper span{display:none}
  .stepper label{justify-content:center;padding-top:11px}
  .cta-in{padding:70px 22px}
  .sticky{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:10px;
    background:rgba(247,244,239,.97);backdrop-filter:blur(12px);border-top:1px solid var(--line);
    padding:11px 14px calc(11px + env(safe-area-inset-bottom))}
  .sticky .btn{flex:1 1 0;min-width:0;padding:15px 8px;font-size:9px;letter-spacing:.1em}
  footer{padding-bottom:78px}
}
@media (max-width:620px){
  .t4,.t3,.t2,.steps,.plan,.loc-grid,.f-top{grid-template-columns:minmax(0,1fr)}
  .gal{grid-template-columns:repeat(2,minmax(0,1fr))}
  .step,.step:nth-child(odd),.step:nth-child(even){border-right:0;padding-left:0;padding-right:0}
  .plan a,.plan a:nth-child(odd){border-right:0}
  .strip .wrap{grid-template-columns:minmax(0,1fr);gap:15px}
  .frow{grid-template-columns:minmax(0,1fr)}
  .f-top{gap:30px}
}
@media (max-width:430px){
  :root{--gut:18px}
  .tile .tb{padding:18px}
  .btn{white-space:normal;text-align:center;padding-left:20px;padding-right:20px;max-width:100%}
  .btnrow{flex-direction:column}
  .btnrow>*{width:100%}
  .faq summary{font-size:18px;padding-right:42px}
}

:root{
  --black:#111213; --ink:#191A1B; --ivory:#F7F3EC; --paper:#FCFAF5; --stone:#D8CFC2;
  --bronze:#B88A55; --bronze-d:#8A6236; --taupe:#9C8875; --clay:#A96658;
  --muted:#6b6157; --line:rgba(17,18,19,.12); --line-soft:rgba(17,18,19,.07);
  --shadow:0 24px 60px rgba(17,18,19,.14); --shadow-sm:0 12px 30px rgba(17,18,19,.08);
  --gut:clamp(18px,5vw,68px); --maxw:1240px; --radius:4px;
  --serif:"Playfair Display",Georgia,"Times New Roman",serif;
  --sans:"Montserrat",-apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;
  --script:"Dancing Script","Playfair Display",cursive;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);color:var(--ink);background:var(--ivory);
  font-size:16px;line-height:1.68;font-weight:400;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--serif);font-weight:600;line-height:1.08;margin:0;letter-spacing:.4px}
p{margin:0 0 1em}
svg{width:20px;height:20px;flex-shrink:0}
.wrap{max-width:var(--maxw);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.eyebrow{font-family:var(--sans);font-weight:700;font-size:.7rem;letter-spacing:.28em;
  text-transform:uppercase;color:var(--bronze-d);margin:0 0 18px}
.script{font-family:var(--script);color:var(--bronze-d);font-weight:400}
.section{padding:clamp(58px,8vw,110px) 0}
.center{text-align:center}
.lead{font-size:clamp(1.02rem,1.35vw,1.16rem);color:var(--muted);max-width:60ch}
.center .lead{margin-left:auto;margin-right:auto}
.skip{position:absolute;left:-999px;top:0;background:var(--black);color:var(--ivory);padding:10px 16px;z-index:200}
.skip:focus{left:0}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,
label:focus-visible,summary:focus-visible{outline:2px solid var(--bronze-d);outline-offset:3px}
/* buttons */
.btn{display:inline-flex;align-items:center;gap:.55em;font-family:var(--sans);font-weight:600;
  font-size:.8rem;letter-spacing:.1em;text-transform:uppercase;padding:15px 28px;border-radius:var(--radius);
  border:1.5px solid var(--black);cursor:pointer;transition:.25s ease;line-height:1.1;text-align:center}
.btn svg{width:16px;height:16px}
.btn-p{background:var(--black);color:var(--ivory);border-color:var(--black)}
.btn-p:hover{background:var(--bronze);border-color:var(--bronze);color:var(--black)}
.btn-o{background:transparent;color:var(--ink);border-color:var(--black)}
.btn-o:hover{background:var(--black);color:var(--ivory)}
.btn-l{background:transparent;color:var(--ivory);border-color:rgba(247,243,236,.5)}
.btn-l:hover{background:var(--ivory);color:var(--black);border-color:var(--ivory)}
.btn-br{background:var(--bronze);color:var(--black);border-color:var(--bronze)}
.btn-br:hover{background:var(--black);color:var(--ivory);border-color:var(--black)}
/* utility bar */
.util{background:var(--black);color:var(--stone);font-size:.72rem;letter-spacing:.12em}
.util .wrap{display:flex;justify-content:space-between;align-items:center;gap:14px;min-height:38px;
  padding-top:9px;padding-bottom:9px}
.util .u-desc{text-transform:uppercase;font-weight:600}
.util .u-r{display:flex;gap:22px;align-items:center}
.util a{color:var(--ivory)}
.util .u-link{display:inline-flex;align-items:center;gap:7px;font-weight:600}
.util .u-link svg{width:13px;height:13px;color:var(--bronze)}
@media(max-width:720px){.util .u-desc{display:none}}
/* header */
.hdr{position:sticky;top:0;z-index:120;background:rgba(247,243,236,.9);
  backdrop-filter:saturate(140%) blur(9px);border-bottom:1px solid var(--line-soft);transition:box-shadow .3s,background .3s}
.hdr-in{max-width:var(--maxw);margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;gap:20px;min-height:80px}
.logo{display:flex;align-items:center;flex:0 0 auto}
.logo img{height:42px;width:auto}
#navtog{position:absolute;opacity:0;width:1px;height:1px;pointer-events:none}
.burger{display:none;margin-left:auto;flex-direction:column;gap:5px;cursor:pointer;padding:11px;border:1px solid var(--line);border-radius:4px}
.burger span{width:22px;height:2px;background:var(--black);display:block;transition:.25s}
.nav{margin-left:auto;display:flex;align-items:center;gap:4px}
.ni{position:relative}
.nlk{display:inline-flex;align-items:center;gap:5px;font-weight:600;font-size:.78rem;letter-spacing:.06em;
  text-transform:uppercase;padding:12px 13px;border-radius:4px;color:var(--ink)}
.nlk:hover{color:var(--bronze-d)}
.ni .caret{width:11px;height:11px;transition:transform .2s;opacity:.6}
.has-drop:hover .caret,.has-drop:focus-within .caret{transform:rotate(180deg)}
.mega{position:absolute;top:calc(100% + 6px);left:0;min-width:258px;background:var(--paper);
  border:1px solid var(--line-soft);box-shadow:var(--shadow-sm);padding:10px;opacity:0;visibility:hidden;
  transform:translateY(8px);transition:.2s ease;z-index:130;border-radius:4px}
.has-drop:hover .mega,.has-drop:focus-within .mega{opacity:1;visibility:visible;transform:translateY(0)}
.mega a{display:block;padding:9px 12px;font-size:.82rem;font-weight:500;color:var(--ink);letter-spacing:.01em}
.mega a:hover{background:var(--ivory);color:var(--bronze-d)}
.mega .mh{font-family:var(--sans);font-size:.62rem;letter-spacing:.2em;text-transform:uppercase;color:var(--bronze-d);padding:8px 12px 4px;font-weight:700}
.hdr-cta{margin-left:8px;flex:0 0 auto;padding:12px 20px;font-size:.72rem}
.hdr.stuck{box-shadow:0 10px 30px rgba(17,18,19,.08);background:rgba(247,243,236,.98)}
@media(max-width:1200px){
  .burger{display:flex}
  .nav{position:fixed;top:0;right:0;height:100vh;width:min(370px,86vw);background:var(--paper);margin:0;
    flex-direction:column;align-items:stretch;gap:0;padding:96px 24px 40px;box-shadow:-20px 0 50px rgba(17,18,19,.18);
    overflow-y:auto;clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .3s ease}
  #navtog:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
  #navtog:checked ~ .burger span:nth-child(1){transform:translateY(7px) rotate(45deg)}
  #navtog:checked ~ .burger span:nth-child(2){opacity:0}
  #navtog:checked ~ .burger span:nth-child(3){transform:translateY(-7px) rotate(-45deg)}
  .nlk{padding:14px 6px;font-size:.82rem;border-bottom:1px solid var(--line-soft);border-radius:0;width:100%}
  .ni{width:100%}.ni .caret{display:none}
  .mega{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:none;background:transparent;padding:2px 0 8px 8px;min-width:0}
  .mega a{padding:8px 10px;font-size:.85rem;text-transform:none}
  .hdr-cta{display:none}
  .nav .m-cta{display:inline-flex;justify-content:center;margin-top:18px}
}
@media(min-width:1201px){.nav .m-cta{display:none}}
/* hero */
.hero{background:var(--ivory);position:relative;overflow:hidden}
.hero-grid{display:grid;grid-template-columns:1.02fr 1.1fr;gap:clamp(30px,4.5vw,72px);align-items:center;
  padding-top:clamp(46px,6vw,84px);padding-bottom:clamp(46px,6vw,84px)}
.hero h1{font-size:clamp(2.5rem,5.6vw,4.4rem);letter-spacing:.5px;margin:2px 0 6px;font-weight:600}
.hero h1 .em{font-style:italic;color:var(--bronze-d);font-weight:500}
.hero .h-script{font-family:var(--script);color:var(--bronze-d);font-size:clamp(1.7rem,3vw,2.5rem);
  font-weight:400;margin:0 0 20px;line-height:1}
.hero-lead{font-size:clamp(1.05rem,1.5vw,1.2rem);color:var(--ink);max-width:46ch;margin-bottom:28px}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:26px}
.hero-tags{display:flex;flex-wrap:wrap;gap:9px}
.hero-tags a{font-size:.72rem;font-weight:600;letter-spacing:.04em;color:var(--ink);border:1px solid var(--line);
  padding:8px 14px;border-radius:40px;background:var(--paper);text-transform:uppercase}
.hero-tags a:hover{border-color:var(--bronze);color:var(--bronze-d)}
/* hero collage */
.collage{position:relative;display:grid;grid-template-columns:1.5fr 1fr;grid-template-rows:auto auto;
  gap:16px;align-items:stretch}
.collage .big{grid-row:1 / span 2;position:relative;border-radius:4px;overflow:hidden;box-shadow:var(--shadow)}
.collage .big img{width:100%;height:100%;object-fit:cover;aspect-ratio:3/4}
.collage .sm{position:relative;border-radius:4px;overflow:hidden;box-shadow:var(--shadow-sm)}
.collage .sm img{width:100%;height:100%;object-fit:cover;aspect-ratio:4/3}
.rec{position:absolute;top:14px;left:14px;display:inline-flex;align-items:center;gap:7px;background:rgba(17,18,19,.72);
  color:var(--ivory);font-family:var(--sans);font-size:.66rem;font-weight:600;letter-spacing:.14em;
  padding:6px 10px;border-radius:3px;backdrop-filter:blur(3px)}
.rec .dot{width:8px;height:8px;border-radius:50%;background:var(--clay);box-shadow:0 0 0 0 rgba(169,102,88,.6);animation:rec 1.6s infinite}
@keyframes rec{0%{box-shadow:0 0 0 0 rgba(169,102,88,.55)}70%{box-shadow:0 0 0 7px rgba(169,102,88,0)}100%{box-shadow:0 0 0 0 rgba(169,102,88,0)}}
.collage .fc{position:absolute;width:30px;height:30px;border:2px solid var(--bronze);z-index:3}
.collage .fc.tl{top:-9px;left:-9px;border-right:0;border-bottom:0}
.collage .fc.br{bottom:-9px;right:-9px;border-left:0;border-top:0}
@media(max-width:900px){.hero-grid{grid-template-columns:1fr;gap:36px}.collage{order:-1}}
@media(max-width:460px){.collage{grid-template-columns:1fr 1fr}.collage .big{grid-row:auto;grid-column:1 / -1}
  .collage .big img{aspect-ratio:16/10}}
/* section head */
.shead{max-width:66ch}.center .shead{margin:0 auto}
.shead.center{max-width:820px;margin-left:auto!important;margin-right:auto!important;text-align:center}
.shead.center .lead{margin-left:auto;margin-right:auto}
.shead .k{font-family:var(--sans);font-weight:700;font-size:.7rem;letter-spacing:.28em;text-transform:uppercase;color:var(--bronze-d);margin:0 0 14px}
.shead h2{font-size:clamp(2rem,3.8vw,3.1rem);margin:0 0 14px;font-weight:600}
.rule{width:46px;height:2px;background:var(--bronze);margin:16px 0 0}
.center .rule{margin-left:auto;margin-right:auto}
/* service strip (dark) */
.strip{background:var(--black);color:var(--ivory)}
.strip .wrap{padding-top:0;padding-bottom:0}
.strip-grid{display:grid;grid-template-columns:repeat(6,1fr)}
.svc{padding:38px 22px;border-right:1px solid rgba(247,243,236,.1);display:flex;flex-direction:column;gap:10px;transition:.25s;position:relative}
.svc:last-child{border-right:0}
.svc:hover{background:rgba(184,138,85,.1)}
.svc .si{width:34px;height:34px;color:var(--bronze)}
.svc .si svg{width:34px;height:34px}
.svc b{font-family:var(--serif);font-weight:600;font-size:1.32rem;color:var(--ivory);letter-spacing:.3px}
.svc span{font-size:.82rem;color:rgba(247,243,236,.66);line-height:1.45}
.svc .go{margin-top:auto;color:var(--bronze);font-size:.68rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;
  display:inline-flex;align-items:center;gap:6px;padding-top:10px}
.svc .go svg{width:13px;height:13px}
@media(max-width:1080px){.strip-grid{grid-template-columns:repeat(3,1fr)}
  .svc:nth-child(3){border-right:0}.svc:nth-child(n+4){border-top:1px solid rgba(247,243,236,.1)}}
@media(max-width:640px){.strip-grid{grid-template-columns:repeat(2,1fr)}
  .svc{border-right:1px solid rgba(247,243,236,.1)!important;border-top:1px solid rgba(247,243,236,.1)}
  .svc:nth-child(odd){border-left:0}.svc:nth-child(even){border-right:0!important}}
@media(max-width:430px){.svc{padding:26px 15px}.svc b{font-size:1.12rem;overflow-wrap:anywhere}.svc span{font-size:.78rem}}
/* specialist grid */
.spec-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:46px}
.spec{display:flex;flex-direction:column;gap:6px;padding:24px 22px;border:1px solid var(--line-soft);
  border-radius:4px;background:var(--paper);transition:.22s}
.spec:hover{border-color:var(--bronze);transform:translateY(-3px);box-shadow:var(--shadow-sm)}
.spec .ic{width:36px;height:36px;color:var(--bronze-d);margin-bottom:8px}
.spec .ic svg{width:26px;height:26px}
.spec b{font-family:var(--serif);font-weight:600;font-size:1.18rem;letter-spacing:.3px}
.spec span{font-size:.79rem;color:var(--muted)}
@media(max-width:900px){.spec-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:460px){.spec-grid{grid-template-columns:1fr}}
/* contact sheet */
.sheet{background:var(--paper);border-top:1px solid var(--line-soft);border-bottom:1px solid var(--line-soft)}
.cs-grid{display:grid;grid-template-columns:repeat(6,1fr);grid-auto-rows:150px;gap:14px;margin-top:48px}
.cs{position:relative;border-radius:4px;overflow:hidden;box-shadow:var(--shadow-sm)}
.cs img{width:100%;height:100%;object-fit:cover}
.cs .cap{position:absolute;left:0;bottom:0;right:0;padding:14px;background:linear-gradient(to top,rgba(17,18,19,.68),transparent);
  color:var(--ivory);font-family:var(--serif);font-weight:600;font-size:1rem;letter-spacing:.3px}
.cs .fn{position:absolute;top:10px;left:12px;font-family:var(--sans);font-size:.6rem;font-weight:600;letter-spacing:.14em;
  color:rgba(247,243,236,.85);background:rgba(17,18,19,.4);padding:3px 7px;border-radius:2px}
.cs-a{grid-column:span 2;grid-row:span 3}
.cs-b{grid-column:span 4;grid-row:span 2}
.cs-c{grid-column:span 3;grid-row:span 2}
.cs-d{grid-column:span 3;grid-row:span 3}
.cs-e{grid-column:span 2;grid-row:span 2}
.cs-f{grid-column:span 4;grid-row:span 2}
@media(max-width:820px){.cs-grid{grid-template-columns:repeat(2,1fr);grid-auto-rows:140px}
  .cs-a,.cs-b,.cs-c,.cs-d,.cs-e,.cs-f{grid-column:span 1;grid-row:span 2}
  .cs-a,.cs-d{grid-row:span 3}}
/* events */
.ev-grid{display:grid;grid-template-columns:repeat(12,1fr);grid-template-rows:clamp(300px,25vw,360px) clamp(240px,20vw,290px);gap:18px;margin-top:46px}
.ev{position:relative;border-radius:4px;overflow:hidden;box-shadow:var(--shadow-sm);grid-column:span 4;height:100%;display:block}
.ev img{width:100%;height:100%;object-fit:cover;transition:.5s}
.ev:hover img{transform:scale(1.05)}
.ev .ov{position:absolute;inset:0;background:linear-gradient(to top,rgba(17,18,19,.74),rgba(17,18,19,.04) 62%);
  display:flex;flex-direction:column;justify-content:flex-end;padding:22px}
.ev .ov b{font-family:var(--serif);font-weight:600;color:var(--ivory);font-size:1.34rem;letter-spacing:.3px}
.ev .ov span{color:var(--stone);font-size:.78rem;font-weight:500;display:inline-flex;align-items:center;gap:6px;text-transform:uppercase;letter-spacing:.06em}
.ev .ov span svg{width:13px;height:13px;color:var(--bronze)}
.ev-lg{grid-column:span 8}
@media(max-width:820px){.ev-grid{grid-template-columns:repeat(2,1fr);grid-template-rows:none;grid-auto-rows:clamp(200px,32vw,250px)}.ev{grid-column:span 1}.ev-lg{grid-column:span 2}}
@media(max-width:520px){.ev-grid{grid-template-columns:1fr;grid-template-rows:none;grid-auto-rows:clamp(190px,56vw,240px)}.ev-lg{grid-column:span 1}.ev{grid-column:span 1}}
/* locations */
.loc{background:var(--black);color:var(--ivory)}
.loc .k{color:var(--bronze)}
.loc h2{color:var(--ivory)}
.loc .lead{color:rgba(247,243,236,.76)}
.loc .rule{background:var(--bronze)}
.state-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:46px}
.state{display:block;padding:26px 22px;border:1px solid rgba(247,243,236,.15);border-radius:4px;background:rgba(247,243,236,.03);transition:.24s}
.state:hover{background:rgba(184,138,85,.1);border-color:var(--bronze);transform:translateY(-3px)}
.state b{font-family:var(--serif);font-weight:600;font-size:1.32rem;display:block;margin-bottom:6px;letter-spacing:.3px}
.state span{font-size:.8rem;color:rgba(247,243,236,.6)}
.state .arw{margin-top:14px;display:inline-flex;align-items:center;gap:7px;color:var(--bronze);font-weight:700;font-size:.68rem;letter-spacing:.12em;text-transform:uppercase}
.chips{margin-top:34px;display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.chips .cl{font-size:.66rem;letter-spacing:.2em;text-transform:uppercase;color:var(--stone);margin-right:6px;font-weight:700}
.chip{font-size:.8rem;font-weight:500;color:var(--ivory);border:1px solid rgba(247,243,236,.22);padding:8px 15px;border-radius:40px;transition:.2s}
.chip:hover{border-color:var(--bronze);color:var(--bronze)}
@media(max-width:900px){.state-grid{grid-template-columns:1fr 1fr}}
@media(max-width:460px){.state-grid{grid-template-columns:1fr}}
/* steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-top:50px}
.step{padding:28px 24px;border-radius:4px;background:var(--paper);border:1px solid var(--line-soft);position:relative}
.step .n{font-family:var(--serif);font-size:2.4rem;font-weight:600;color:var(--bronze);line-height:1;margin-bottom:14px}
.step h3{font-size:1.24rem;margin:0 0 8px;font-weight:600}
.step p{font-size:.86rem;color:var(--muted);margin:0}
@media(max-width:880px){.steps{grid-template-columns:1fr 1fr}}
@media(max-width:460px){.steps{grid-template-columns:1fr}}
/* more ways */
.more-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:44px}
.mcard{display:flex;gap:16px;padding:26px;border-radius:4px;background:var(--paper);border:1px solid var(--line-soft);transition:.24s}
.mcard:hover{border-color:var(--bronze);transform:translateY(-3px)}
.mcard .mi{width:42px;height:42px;flex:0 0 auto;color:var(--bronze-d)}
.mcard .mi svg{width:32px;height:32px}
.mcard b{font-family:var(--serif);font-weight:600;font-size:1.18rem;display:block;margin-bottom:5px;letter-spacing:.3px}
.mcard p{font-size:.84rem;color:var(--muted);margin:0 0 10px}
.mcard .go{font-weight:700;font-size:.68rem;letter-spacing:.12em;text-transform:uppercase;color:var(--bronze-d);display:inline-flex;align-items:center;gap:6px}
.mcard .go svg{width:13px;height:13px}
@media(max-width:860px){.more-grid{grid-template-columns:1fr}}
/* about */
.about-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:clamp(30px,4.5vw,64px);align-items:center}
.about-media{position:relative}
.about-media img{border-radius:4px;box-shadow:var(--shadow);aspect-ratio:5/4;object-fit:cover;width:100%}
.about-media .fc{position:absolute;width:34px;height:34px;border:2px solid var(--bronze);z-index:2}
.about-media .fc.tl{top:-10px;left:-10px;border-right:0;border-bottom:0}
.about-media .fc.br{bottom:-10px;right:-10px;border-left:0;border-top:0}
.about-media .stamp{position:absolute;right:-16px;bottom:-16px;width:118px;height:118px;border-radius:50%;
  background:var(--black);color:var(--ivory);display:flex;flex-direction:column;align-items:center;justify-content:center;
  text-align:center;padding:12px;box-shadow:var(--shadow)}
.about-media .stamp b{font-family:var(--serif);color:var(--bronze);font-size:1.7rem;line-height:1;font-weight:600}
.about-media .stamp span{font-size:.56rem;letter-spacing:.14em;text-transform:uppercase;margin-top:5px;color:var(--stone)}
@media(max-width:820px){.about-grid{grid-template-columns:1fr}.about-media{max-width:440px}}
/* essence band */
.essence{background:var(--stone);color:var(--black);text-align:center}
.essence .fl{font-family:var(--sans);font-weight:700;font-size:.68rem;letter-spacing:.26em;text-transform:uppercase;color:var(--bronze-d);margin:0 0 20px}
.essence h2{font-size:clamp(2rem,4.4vw,3.4rem);max-width:20ch;margin:0 auto 20px;font-weight:600;line-height:1.12}
.essence h2 .em{font-style:italic;color:var(--bronze-d)}
.essence p{font-size:clamp(1rem,1.4vw,1.16rem);color:var(--ink);max-width:52ch;margin:0 auto}
/* enquiry */
.enq{background:var(--paper);border-top:1px solid var(--line-soft)}
.enq-grid{display:grid;grid-template-columns:.92fr 1.08fr;gap:clamp(30px,4vw,64px);align-items:start}
.enq-info .rule{background:var(--bronze)}
.enq-list{list-style:none;padding:0;margin:26px 0 0}
.enq-list li{display:flex;gap:12px;align-items:flex-start;margin-bottom:16px;font-size:.92rem;color:var(--ink)}
.enq-list li svg{width:20px;height:20px;color:var(--bronze-d);margin-top:2px}
.form{background:var(--ivory);border:1px solid var(--line-soft);border-radius:6px;padding:clamp(22px,3vw,36px)}
.form h3{font-size:1.5rem;margin:0 0 4px;font-weight:600}
.form .fnote{font-size:.82rem;color:var(--muted);margin:0 0 20px}
.frow{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.field{display:flex;flex-direction:column;gap:6px;margin-bottom:16px;min-width:0}
.field.full{grid-column:1/-1}
.field label{font-size:.74rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--ink)}
.field label .req{color:var(--clay)}
.field input,.field select,.field textarea{width:100%;min-width:0;font-family:var(--sans);font-size:.92rem;
  padding:12px 14px;border:1px solid var(--line);border-radius:4px;background:#fff;color:var(--ink)}
.field textarea{resize:vertical;min-height:96px}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--bronze-d);outline:none;box-shadow:0 0 0 3px rgba(138,98,54,.14)}
.form .submit{width:100%;justify-content:center;margin-top:6px;padding:16px}
.form .privacy{font-size:.72rem;color:var(--muted);margin:14px 0 0;line-height:1.5}
.form .privacy a{color:var(--bronze-d);text-decoration:underline}
@media(max-width:860px){.enq-grid{grid-template-columns:1fr}}
@media(max-width:520px){.frow{grid-template-columns:1fr}}
/* cta band */
.cta{background:var(--black);color:var(--ivory);text-align:center;position:relative;overflow:hidden}
.cta .h-script{font-family:var(--script);color:var(--bronze);font-size:clamp(1.7rem,3.4vw,2.6rem);font-weight:400;margin:0 0 12px;line-height:1}
.cta h2{color:var(--ivory);font-size:clamp(2rem,4vw,3.1rem);margin:0 0 16px;font-weight:600}
.cta p{color:rgba(247,243,236,.78);max-width:54ch;margin:0 auto 30px}
.cta .row{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}
/* footer */
footer{background:var(--black);color:var(--stone);padding:66px 0 26px}
.f-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:36px;padding-bottom:44px;border-bottom:1px solid rgba(247,243,236,.12)}
.f-brand img{height:36px;margin-bottom:18px}
.f-brand .ftag{font-family:var(--script);color:var(--bronze);font-size:1.4rem;margin:0 0 12px;line-height:1;font-weight:400}
.f-brand .fdesc{font-size:.84rem;color:rgba(247,243,236,.6);max-width:34ch;margin:0 0 16px}
.f-brand .fmem{font-size:.76rem;color:rgba(247,243,236,.48)}
.f-brand .fmem b{color:var(--bronze);font-weight:600}
.fcol h4{font-family:var(--sans);font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;color:var(--bronze);margin:0 0 16px;font-weight:700}
.fcol a{display:block;font-size:.85rem;color:rgba(247,243,236,.76);padding:6px 0}
.fcol a:hover{color:var(--bronze)}
.f-bot{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;padding-top:24px}
.f-bot .legal{display:flex;gap:18px;flex-wrap:wrap;font-size:.78rem;align-items:center}
.f-bot .legal a{color:rgba(247,243,236,.58)}
.f-bot .legal a:hover{color:var(--bronze)}
.built{display:inline-flex;align-items:center;gap:9px;font-size:.78rem;color:rgba(247,243,236,.58)}
.built b{color:var(--bronze);font-weight:600}
.built-ico{width:26px;height:26px;border-radius:6px}
@media(max-width:860px){.f-top{grid-template-columns:1fr 1fr}.f-brand{grid-column:1/-1}}
@media(max-width:480px){.f-top{grid-template-columns:1fr}}
/* mobile bar */
.mbar{position:fixed;left:0;right:0;bottom:0;z-index:110;display:none;background:var(--black);border-top:1px solid rgba(247,243,236,.14);padding:10px 14px}
.mbar a{flex:1;justify-content:center;font-size:.72rem;padding:13px}
@media(max-width:1200px){.mbar{display:flex;gap:10px}body{padding-bottom:70px}}
/* reveal */
.rv{animation:rvIn .8s both}.rv.d1{animation-delay:.08s}.rv.d2{animation-delay:.16s}.rv.d3{animation-delay:.24s}
@keyframes rvIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}
  .rv{opacity:1!important;transform:none!important}.rec .dot{animation:none!important}}


/* =========================================================
   V4 BRAND GUIDELINE TYPOGRAPHY + EDITABLE IMAGE SLOTS
   Headings/Logo: Playfair Display
   Body/UI: Montserrat
   Accent/Script: Dancing Script
   ========================================================= */

/* Playfair reads best with slightly tighter display tracking. */
h1,h2,h3,h4{letter-spacing:-.015em}
.hero h1{letter-spacing:-.025em}
.svc b,.spec b,.ev .ov b,.state b,.step h3,.mcard b{letter-spacing:-.01em}
.hero .h-script,.cta .h-script,.f-brand .ftag,.script{font-weight:400;letter-spacing:0}

/* Specialist image cards */
.spec{padding:0;overflow:hidden;gap:0;background:#fff}
.spec-media{display:block;aspect-ratio:16/10;overflow:hidden;background:#e9e7ef}
.spec-media img{width:100%;height:100%;display:block;object-fit:cover;transition:transform .5s ease}
.spec:hover .spec-media img{transform:scale(1.055)}
.spec-copy{display:flex;flex-direction:column;gap:6px;padding:20px 20px 22px;min-height:168px}
.spec-copy .ic{margin-bottom:7px}

/* Location cards now have replaceable lifestyle photography. */
.state{padding:0;overflow:hidden;background:rgba(255,255,255,.06)}
.state-media{display:block;aspect-ratio:16/9;overflow:hidden;background:rgba(255,255,255,.08)}
.state-media img{width:100%;height:100%;display:block;object-fit:cover;filter:saturate(.92);transition:transform .55s ease,filter .3s ease}
.state:hover .state-media img{transform:scale(1.05);filter:saturate(1.08)}
.state-copy{display:block;padding:22px 22px 24px}
.state-copy>b,.state-copy>span{display:block}
.state-copy .arw{display:inline-flex}

/* Extra services use image-first cards rather than icon-only blocks. */
.mcard{padding:0;display:flex;flex-direction:column;gap:0;overflow:hidden}
.mcard-media{display:block;width:100%;aspect-ratio:16/9;overflow:hidden;background:#e9e7ef}
.mcard-media img{width:100%;height:100%;display:block;object-fit:cover;transition:transform .5s ease}
.mcard:hover .mcard-media img{transform:scale(1.05)}
.mcard-copy{display:grid;grid-template-columns:42px 1fr;gap:16px;padding:22px 24px 25px;align-items:start}
.mcard-copy>.mi{grid-column:1}
.mcard-copy>div{grid-column:2}

/* Optional replaceable photographic backgrounds. The image is applied only when a URL is added to IMAGE_LIBRARY. */
.editable-bg{position:relative;isolation:isolate;overflow:hidden}
.editable-bg::before{content:"";position:absolute;inset:0;background-image:var(--editable-bg-image,none);background-size:cover;background-position:center;opacity:var(--editable-bg-opacity,0);z-index:-2}
.editable-bg::after{content:"";position:absolute;inset:0;background:var(--editable-bg-overlay,transparent);z-index:-1;pointer-events:none}
.loc.editable-bg{--editable-bg-overlay:linear-gradient(90deg,rgba(20,34,110,.90),rgba(49,91,255,.84));--editable-bg-opacity:.30}
.essence.editable-bg{--editable-bg-overlay:linear-gradient(110deg,rgba(255,87,126,.92),rgba(128,87,245,.86));--editable-bg-opacity:.24}
.cta.editable-bg{--editable-bg-overlay:linear-gradient(110deg,rgba(10,12,24,.91),rgba(17,27,58,.88));--editable-bg-opacity:.34}

@media(max-width:900px){
  .spec-copy{min-height:0}
}



/* ==========================================================
   REEL THE MOMENT — V3 "CHROMATIC REEL"
   Direction: editorial photography + cinematic RGB/light-leak energy.
   Keeps the existing information architecture while breaking up the
   previous ivory/black/bronze repetition with intentional section tones.
   ========================================================== */
:root{
  --black:#090D18;
  --ink:#111526;
  --ivory:#FFF7EF;
  --paper:#FFFFFF;
  --stone:#E9EAF2;
  --bronze:#FF5F68;
  --bronze-d:#315BFF;
  --taupe:#73778A;
  --clay:#FF4667;
  --muted:#3F4557;
  --line:rgba(17,21,38,.12);
  --line-soft:rgba(17,21,38,.075);
  --shadow:0 28px 70px rgba(10,15,35,.18);
  --shadow-sm:0 14px 38px rgba(10,15,35,.10);
  --cobalt:#315BFF;
  --cyan:#11BFD4;
  --coral:#FF5F68;
  --amber:#FFBE38;
  --violet:#8057F5;
  --teal:#0CA899;
  --berry:#DD3E82;
  --sky:#EAF1FF;
  --lav:#F0EAFE;
  --mint:#E7FAF6;
  --peach:#FFF0E8;
  --butter:#FFF5CE;
}

body{background:#fff;color:var(--ink)}
.section{position:relative;overflow:hidden}
.wrap{max-width:1280px}
.eyebrow,.shead .k{color:var(--cobalt)}
.rule{background:linear-gradient(90deg,var(--cobalt),var(--coral),var(--amber));width:78px;height:4px;border-radius:10px}
.lead{color:var(--muted)}

/* Buttons */
.btn{border-radius:999px;padding:15px 26px;font-weight:800;letter-spacing:.08em;box-shadow:none}
.btn-p{background:var(--cobalt);border-color:var(--cobalt);color:#fff}
.btn-p:hover{background:#173FE5;border-color:#173FE5;color:#fff;transform:translateY(-2px)}
.btn-o{background:#fff;color:var(--ink);border-color:rgba(17,21,38,.20)}
.btn-o:hover{background:var(--ink);border-color:var(--ink);color:#fff;transform:translateY(-2px)}
.btn-br{background:var(--amber);color:var(--ink);border-color:var(--amber)}
.btn-br:hover{background:#fff;border-color:#fff;color:var(--ink);transform:translateY(-2px)}

/* Utility + header */
.util{background:linear-gradient(90deg,#315BFF 0%,#6F4CF6 48%,#E84786 100%);color:#fff}
.util a,.util .u-link svg{color:#fff}
.hdr{background:rgba(255,255,255,.90);border-bottom:1px solid rgba(17,21,38,.08);box-shadow:0 8px 30px rgba(18,24,50,.05)}
.hdr.stuck{background:rgba(255,255,255,.97);box-shadow:0 12px 36px rgba(18,24,50,.11)}
.nlk:hover{color:var(--cobalt)}
.mega{background:#fff;border-color:rgba(17,21,38,.08);border-radius:18px;box-shadow:0 24px 60px rgba(9,13,24,.15)}
.mega a:hover{background:var(--sky);color:var(--cobalt)}
.mega .mh{color:var(--cobalt)}
.burger{border-radius:12px}

/* HERO — dark cinematic stage with RGB/light-leak glows */
.hero{
  background:
    radial-gradient(circle at 88% 15%,rgba(255,82,112,.36),transparent 24%),
    radial-gradient(circle at 68% 85%,rgba(49,91,255,.42),transparent 28%),
    radial-gradient(circle at 12% 0%,rgba(128,87,245,.28),transparent 24%),
    linear-gradient(135deg,#080B14 0%,#111733 52%,#090D18 100%);
  color:#fff;
}
.hero::before{
  content:"";position:absolute;inset:0;pointer-events:none;opacity:.34;
  background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);
  background-size:42px 42px;
  mask-image:linear-gradient(to bottom,black,transparent 88%);
}
.hero::after{
  content:"";position:absolute;left:0;right:0;bottom:0;height:7px;
  background:linear-gradient(90deg,var(--cobalt) 0 20%,var(--cyan) 20% 37%,var(--amber) 37% 54%,var(--coral) 54% 73%,var(--violet) 73% 100%);
}
.hero-grid{position:relative;z-index:2;padding-top:clamp(64px,7vw,108px);padding-bottom:clamp(66px,7vw,108px)}
.hero .eyebrow{color:#9FDFFF;background:rgba(17,191,212,.12);border:1px solid rgba(17,191,212,.28);display:inline-flex;padding:8px 13px;border-radius:999px;letter-spacing:.2em}
.hero h1{color:#fff;font-size:clamp(3.05rem,4.35vw,4.35rem);line-height:.99;letter-spacing:-.025em;max-width:none}
.hero h1 .hb{display:block}
.hero h1 .em{
  background:linear-gradient(90deg,#FFD05A 0%,#FF6E7D 48%,#A87CFF 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent;font-style:italic;
}
.hero .h-script{color:#FFD46D;font-size:clamp(1.8rem,3vw,2.65rem)}
.hero-lead{color:rgba(255,255,255,.78);font-size:clamp(1.04rem,1.4vw,1.2rem)}
.hero .btn-p{background:var(--coral);border-color:var(--coral)}
.hero .btn-p:hover{background:#fff;border-color:#fff;color:var(--ink)}
.hero .btn-o{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.42);color:#fff;backdrop-filter:blur(8px)}
.hero .btn-o:hover{background:#fff;color:var(--ink);border-color:#fff}
.hero-tags a{background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.16);color:rgba(255,255,255,.82);backdrop-filter:blur(8px)}
.hero-tags a:hover{background:rgba(255,255,255,.14);border-color:#8DE6F1;color:#fff}
.collage{gap:18px;transform:rotate(-.7deg)}
.collage .big,.collage .sm{border-radius:22px;border:1px solid rgba(255,255,255,.17);box-shadow:0 30px 80px rgba(0,0,0,.38)}
.collage .sm:first-of-type{transform:translateY(18px) rotate(2deg)}
.collage .sm:last-of-type{transform:translateY(-4px) rotate(-2deg)}
.collage .fc{border-width:3px}
.collage .fc.tl{border-color:var(--cyan)}
.collage .fc.br{border-color:var(--coral)}
.rec{background:rgba(7,10,18,.75);border:1px solid rgba(255,255,255,.16);border-radius:999px}
.rec .dot{background:#FF385F}

/* COLOR DECK — service discovery */
.strip{background:#fff;color:var(--ink);padding:34px 0 48px}
.strip-grid{grid-template-columns:repeat(3,1fr);gap:14px}
.svc{border:0!important;border-radius:22px;padding:30px 28px;min-height:190px;color:#fff;box-shadow:0 16px 38px rgba(18,24,50,.10);overflow:hidden;isolation:isolate;transform:translateZ(0)}
.svc::before{content:"";position:absolute;width:130px;height:130px;border:26px solid rgba(255,255,255,.13);border-radius:50%;right:-40px;top:-48px;z-index:-1}
.svc::after{content:"";position:absolute;left:28px;right:28px;bottom:0;height:3px;background:rgba(255,255,255,.40);transform:scaleX(.22);transform-origin:left;transition:.28s}
.svc:hover{transform:translateY(-7px);box-shadow:0 25px 55px rgba(18,24,50,.17)}
.svc:hover::after{transform:scaleX(1)}
.svc:nth-child(1){background:linear-gradient(135deg,#2453FF,#4177FF)}
.svc:nth-child(2){background:linear-gradient(135deg,#7048EF,#9B61FF)}
.svc:nth-child(3){background:linear-gradient(135deg,#F94C72,#FF786D)}
.svc:nth-child(4){background:linear-gradient(135deg,#FFAE26,#FFD35E);color:#171521}
.svc:nth-child(5){background:linear-gradient(135deg,#009A92,#19C8B8)}
.svc:nth-child(6){background:linear-gradient(135deg,#121728,#252C46)}
.svc .si,.svc .go{color:inherit}
.svc b{font-size:1.55rem;color:inherit}
.svc span{color:inherit;opacity:.88}
.svc .go{opacity:1}
.svc:nth-child(4) .si,.svc:nth-child(4) .go{color:#171521}

/* Specialist directory — clean cards, chromatic tabs */
.specialist-zone{background:linear-gradient(180deg,#F6F8FF 0%,#FFFFFF 100%)}
.spec-grid{gap:18px}
.spec{position:relative;overflow:hidden;border:1px solid rgba(17,21,38,.08);border-radius:20px;background:#fff;padding:27px 24px 25px;box-shadow:0 10px 30px rgba(25,34,70,.055)}
.spec::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:var(--c,var(--cobalt))}
.spec:nth-child(1){--c:#FF5F68}.spec:nth-child(2){--c:#315BFF}.spec:nth-child(3){--c:#DD3E82}.spec:nth-child(4){--c:#0CA899}
.spec:nth-child(5){--c:#8057F5}.spec:nth-child(6){--c:#11BFD4}.spec:nth-child(7){--c:#FF9A30}.spec:nth-child(8){--c:#141A2C}
.spec .ic{color:var(--c)!important;background:color-mix(in srgb,var(--c) 11%,white);width:46px;height:46px;border-radius:14px;display:grid;place-items:center}
.spec:hover{border-color:color-mix(in srgb,var(--c) 45%,white);box-shadow:0 20px 42px color-mix(in srgb,var(--c) 13%,transparent);transform:translateY(-6px)}
.spec b{font-size:1.23rem}

/* Portfolio wall — almost black so imagery becomes the colour */
.gallery-zone{background:#090D18!important;border:0!important;color:#fff}
.gallery-zone::before{content:"";position:absolute;inset:auto -10% -40% 45%;height:65%;background:radial-gradient(circle,rgba(49,91,255,.20),transparent 65%);pointer-events:none}
.gallery-zone .shead .k{color:#7FE8F1}
.gallery-zone .shead h2{color:#fff}
.gallery-zone .lead{color:rgba(255,255,255,.68)}
.gallery-zone .rule{background:linear-gradient(90deg,var(--cyan),var(--coral),var(--amber))}
.gallery-zone .cs-grid{gap:16px}
.gallery-zone .cs{border-radius:18px;box-shadow:0 15px 40px rgba(0,0,0,.35);border:1px solid rgba(255,255,255,.12)}
.gallery-zone .cs img{transition:transform .55s ease,filter .55s ease;filter:saturate(1.03) contrast(1.02)}
.gallery-zone .cs:hover img{transform:scale(1.045);filter:saturate(1.18) contrast(1.04)}
.gallery-zone .cs:nth-child(1){box-shadow:0 0 0 2px rgba(255,95,104,.65),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(2){box-shadow:0 0 0 2px rgba(49,91,255,.70),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(3){box-shadow:0 0 0 2px rgba(128,87,245,.70),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(4){box-shadow:0 0 0 2px rgba(12,168,153,.68),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(5){box-shadow:0 0 0 2px rgba(255,190,56,.70),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(6){box-shadow:0 0 0 2px rgba(17,191,212,.68),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .btn-o{background:transparent;color:#fff;border-color:rgba(255,255,255,.35)}
.gallery-zone .btn-o:hover{background:#fff;color:var(--ink);border-color:#fff}

/* Events — warm gallery page */
.events-zone{background:linear-gradient(180deg,#FFF4EC 0%,#FFFDFC 100%)}
.events-zone .shead .k{color:#E54C76}
.ev-grid{gap:18px}
.ev{border-radius:24px;box-shadow:0 18px 45px rgba(45,24,20,.14)}
.ev::after{content:"";position:absolute;inset:0;border:2px solid transparent;border-radius:inherit;transition:.3s;pointer-events:none}
.ev:hover::after{border-color:rgba(255,255,255,.7);inset:9px}
.ev .ov{padding:26px;background:linear-gradient(to top,rgba(8,10,18,.85),rgba(8,10,18,.04) 67%)}
.ev .ov b{font-size:1.55rem}
.ev .ov span svg{color:#FFD36A}

/* Locations — electric blue geographic hub */
.loc{
  background:
    radial-gradient(circle at 14% 20%,rgba(17,191,212,.34),transparent 24%),
    radial-gradient(circle at 92% 90%,rgba(128,87,245,.40),transparent 26%),
    linear-gradient(135deg,#1747E8 0%,#315BFF 48%,#5535CC 100%);
  color:#fff;
}
.loc .k{color:#B8F4F7}
.loc h2{color:#fff}
.loc .lead{color:rgba(255,255,255,.78)}
.loc .rule{background:linear-gradient(90deg,#86F0F6,#FFD768,#FF8BA0)}
.state-grid{gap:14px}
.state{border-color:rgba(255,255,255,.22);border-radius:20px;background:rgba(255,255,255,.10);backdrop-filter:blur(8px);padding:29px 24px}
.state:hover{background:#fff;color:var(--ink);border-color:#fff;transform:translateY(-6px);box-shadow:0 22px 45px rgba(15,28,82,.23)}
.state:hover span{color:var(--muted)}
.state:hover .arw{color:var(--cobalt)}
.state .arw{color:#FFF0A9}
.chip{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.25);color:#fff}
.chip:hover{background:#fff;color:var(--cobalt);border-color:#fff}

/* How it works — playful film/contact-sheet numbering */
.how-zone{background:var(--butter)}
.how-zone .shead .k{color:#9A6D00}
.steps{gap:16px}
.step{border:0;border-radius:22px;background:#fff;padding:31px 25px;box-shadow:0 12px 34px rgba(80,65,15,.08);overflow:hidden}
.step::after{content:"";position:absolute;right:-30px;top:-30px;width:92px;height:92px;border-radius:50%;background:var(--step-color);opacity:.10}
.step:nth-child(1){--step-color:#315BFF}.step:nth-child(2){--step-color:#8057F5}.step:nth-child(3){--step-color:#FF5F68}.step:nth-child(4){--step-color:#0CA899}
.step .n{display:grid;place-items:center;width:54px;height:54px;border-radius:16px;background:var(--step-color);color:#fff;font-family:var(--sans);font-size:1.25rem;font-weight:800}
.step h3{margin-top:18px}

/* More ways — mint content-creator panel */
.more-zone{background:var(--mint)!important;border:0!important}
.more-zone .shead .k{color:#087A70}
.mcard{border:1px solid rgba(17,21,38,.08);border-radius:22px;background:#fff;padding:28px;box-shadow:0 12px 32px rgba(7,92,82,.07)}
.mcard:nth-child(1){--mc:#315BFF}.mcard:nth-child(2){--mc:#DD3E82}.mcard:nth-child(3){--mc:#FF9A30}
.mcard .mi{color:var(--mc);background:color-mix(in srgb,var(--mc) 11%,white);border-radius:15px;display:grid;place-items:center;width:54px;height:54px}
.mcard .go{color:var(--mc)}
.mcard:hover{border-color:color-mix(in srgb,var(--mc) 40%,white);box-shadow:0 18px 44px color-mix(in srgb,var(--mc) 12%,transparent);transform:translateY(-6px)}

/* About — clean editorial reset with a bold image frame */
.about-zone{background:#fff}
.about-zone::after{content:"";position:absolute;right:-100px;top:55px;width:310px;height:310px;border-radius:50%;background:radial-gradient(circle,rgba(255,95,104,.13),transparent 68%);pointer-events:none}
.about-media img{border-radius:26px;box-shadow:0 24px 60px rgba(19,24,50,.16)}
.about-media .fc{border-width:4px}.about-media .fc.tl{border-color:var(--cobalt)}.about-media .fc.br{border-color:var(--coral)}
.about-media .stamp{background:linear-gradient(145deg,#8057F5,#315BFF);color:#fff;width:132px;height:132px;border:5px solid #fff}
.about-media .stamp b{color:#FFD86E}
.about-zone .about-copy .k{color:var(--cobalt)!important}
.about-zone .about-copy h2 span{color:var(--coral)!important}

/* Brand essence — a photographic light leak instead of a flat beige band */
.essence{
  background:
    radial-gradient(circle at 18% 30%,rgba(255,255,255,.34),transparent 20%),
    radial-gradient(circle at 82% 60%,rgba(128,87,245,.36),transparent 25%),
    linear-gradient(120deg,#FFB439 0%,#FF7069 42%,#E8438B 70%,#7C59F6 100%);
  color:#111526;
}
.essence .fl{color:#111526;background:rgba(255,255,255,.42);display:inline-flex;padding:7px 12px;border-radius:999px}
.essence h2{max-width:23ch;color:#111526}
.essence h2 .em{color:#fff;text-shadow:0 2px 20px rgba(72,20,79,.18)}
.essence p{color:rgba(17,21,38,.82)}

/* Enquiry — soft chromatic background, bright white form */
.enq{background:linear-gradient(135deg,#EEF3FF 0%,#F3EAFF 48%,#E8FAF5 100%);border:0}
.enq::before{content:"";position:absolute;left:-80px;bottom:-100px;width:260px;height:260px;border-radius:50%;background:radial-gradient(circle,rgba(17,191,212,.16),transparent 68%)}
.enq .enq-info .k{color:var(--cobalt)!important}
.enq-list li svg{color:var(--teal)}
.form{position:relative;overflow:hidden;background:#fff;border:1px solid rgba(17,21,38,.08);border-radius:24px;padding:clamp(26px,3vw,40px);box-shadow:0 28px 70px rgba(40,50,100,.13)}
.form::before{content:"";position:absolute;left:0;right:0;top:0;height:7px;background:linear-gradient(90deg,var(--cobalt),var(--cyan),var(--amber),var(--coral),var(--violet))}
.field input,.field select,.field textarea{border-radius:12px;background:#FAFBFE;border-color:rgba(17,21,38,.12);padding:13px 14px}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--cobalt);box-shadow:0 0 0 4px rgba(49,91,255,.12)}
.form .privacy a{color:var(--cobalt)}

/* Final CTA — second cinematic scene, not a repeat of footer black */
.cta{
  background:
    radial-gradient(circle at 16% 0%,rgba(17,191,212,.30),transparent 25%),
    radial-gradient(circle at 84% 100%,rgba(255,70,103,.36),transparent 27%),
    linear-gradient(130deg,#0B1022 0%,#172254 45%,#351A63 100%);
  color:#fff;
}
.cta .h-script{color:#FFD369}
.cta h2{color:#fff}
.cta p{color:rgba(255,255,255,.77)}
.cta .btn-br{background:var(--coral);border-color:var(--coral);color:#fff}
.cta .btn-br:hover{background:#fff;border-color:#fff;color:var(--ink)}

/* Footer remains the visual anchor */
footer{background:#080B13;color:#D9DCE8}
.f-brand .ftag,.fcol h4,.f-brand .fmem b,.built b{color:#FFD369}
.fcol a:hover,.f-bot .legal a:hover{color:#8DE8F0}
.mbar{background:#080B13}

/* Motion/details */
.svc,.spec,.state,.step,.mcard,.ev,.btn{transition:transform .28s ease,box-shadow .28s ease,border-color .28s ease,background .28s ease,color .28s ease}

/* Responsive */
@media(max-width:1080px){
  .strip-grid{grid-template-columns:repeat(2,1fr)}
  .svc{border:0!important}
}
@media(max-width:900px){
  .hero h1{max-width:none}
  .collage{transform:none;order:-1}
  .about-zone::after{display:none}
}
@media(max-width:640px){
  .strip{padding:22px 0 34px}
  .strip-grid{grid-template-columns:1fr;gap:10px}
  .svc{min-height:155px;padding:25px 22px}
  .svc b{font-size:1.38rem}
  .hero-grid{padding-top:38px;padding-bottom:58px}
  .hero h1{font-size:clamp(1.9rem,10vw,2.6rem)}
  .hero .eyebrow{font-size:.62rem}
  .state,.step,.mcard,.spec{border-radius:18px}
}
@media(prefers-reduced-motion:reduce){.svc:hover,.spec:hover,.state:hover,.mcard:hover,.btn:hover{transform:none!important}}



/* ---- Brand-brief typography tuning (Playfair Display) ---- */
h1,h2,h3,h4{font-weight:600}
.hero h1{font-weight:600;letter-spacing:-.01em;line-height:1.0}
.essence h2,.cta h2,.shead h2{font-weight:600}
.svc b,.spec b,.ev .ov b,.state b{font-weight:600}
.h-script,.ftag,.script{font-weight:600}

/* ---- HERO: balance the stage, reduce empty space ---- */
.hero-grid{gap:clamp(28px,3vw,52px);align-items:center;
  padding-top:clamp(34px,3.6vw,60px);padding-bottom:clamp(44px,5vw,80px)}
@media(min-width:901px){.hero-grid{grid-template-columns:1.06fr 1fr}}
.collage{transform:rotate(-.35deg);gap:16px;align-items:stretch}
.collage .sm:first-of-type{transform:translateY(12px) rotate(1.4deg)}
.collage .sm:last-of-type{transform:translateY(-2px) rotate(-1.4deg)}
.collage .big img{aspect-ratio:auto;height:100%;min-height:460px}
.collage .sm img{aspect-ratio:auto;height:100%;min-height:150px}
@media(max-width:900px){.collage .big img{min-height:0;aspect-ratio:3/4}
  .collage .sm img{min-height:0;aspect-ratio:4/3}}

/* ---- Tighter, more even section rhythm ---- */
.section{padding-top:clamp(52px,7vw,94px);padding-bottom:clamp(52px,7vw,94px)}
.shead{margin-bottom:2px}
.spec-grid,.cs-grid,.ev-grid,.state-grid,.steps,.more-grid{margin-top:clamp(32px,4vw,46px)}
.essence.section{padding-top:clamp(50px,6vw,84px);padding-bottom:clamp(50px,6vw,84px)}
.essence p{margin-top:6px}

/* ---- CONTACT SHEET: 8-tile editorial mosaic (no gaps) ---- */
.cs-grid{grid-template-columns:repeat(6,1fr);grid-auto-rows:170px;gap:16px}
.cs{grid-row:span 2}
.t1{grid-column:span 2}.t2{grid-column:span 4}
.t3{grid-column:span 4}.t4{grid-column:span 2}
.t5{grid-column:span 3}.t6{grid-column:span 3}
.t7{grid-column:span 2}.t8{grid-column:span 4}
@media(max-width:820px){.cs-grid{grid-template-columns:repeat(2,1fr);grid-auto-rows:150px}
  .t1,.t2,.t3,.t4,.t5,.t6,.t7,.t8{grid-column:span 1;grid-row:span 2}}
@media(max-width:460px){.cs-grid{grid-template-columns:1fr}}

/* ---- Specialist cards: even heights ---- */
.spec-copy{min-height:150px}
@media(max-width:900px){.spec-copy{min-height:0}}

/* ---- Keep the image "Add your photo" chips from feeling flat: subtle frame ---- */
.spec-media,.state-media,.mcard-media,.collage .big,.collage .sm,.cs,.ev,.about-media img{background:#0e1120}



.strip{background:linear-gradient(180deg,#FFFFFF 0%,#F5F8FF 100%)!important;color:var(--ink)!important;padding:clamp(42px,5vw,66px) 0 clamp(50px,6vw,74px)!important}
.strip .wrap{padding-top:0;padding-bottom:0}
.strip-grid{gap:16px}
.svc{background:#fff!important;color:#161a29!important;border:1px solid rgba(20,30,60,.09)!important;border-radius:20px!important;
  padding:26px 24px 24px!important;min-height:176px!important;box-shadow:0 10px 26px rgba(24,34,70,.06)!important;
  overflow:hidden;isolation:isolate}
.svc::before{content:""!important;position:absolute!important;top:0!important;left:0!important;right:0!important;bottom:auto!important;
  width:auto!important;height:4px!important;border:0!important;border-radius:0!important;
  background:var(--acc,#3358E0)!important;opacity:.95;z-index:1}
.svc::after{display:none!important}
.svc .si{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;
  background:var(--chip,#EDF1FF)!important;color:var(--acc,#3358E0)!important}
.svc .si svg{width:24px;height:24px}
.svc b{color:#161a29!important;font-family:var(--serif);font-weight:700;font-size:1.3rem;letter-spacing:.2px}
.svc span{color:#59607200!important;color:#5a6072!important;font-size:.86rem;line-height:1.5}
.svc .go{color:var(--acc,#3358E0)!important;margin-top:auto;font-size:.68rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase}
.svc:hover{background:#fff!important;transform:translateY(-6px)!important;box-shadow:0 24px 48px rgba(24,34,70,.13)!important}
.svc:nth-child(1){--acc:#3358E0;--chip:#EBF0FF}
.svc:nth-child(2){--acc:#7A50EC;--chip:#F1ECFE}
.svc:nth-child(3){--acc:#E24C74;--chip:#FDECF1}
.svc:nth-child(4){--acc:#C07E10;--chip:#FBF2DC}
.svc:nth-child(5){--acc:#0E9E90;--chip:#E6F7F3}
.svc:nth-child(6){--acc:#2E3552;--chip:#EDEFF6}
.svc:nth-child(4) .si,.svc:nth-child(4) .go{color:var(--acc)!important}
@media(max-width:640px){.svc{min-height:150px!important;padding:22px 20px!important}}

.svc.svc-img{background:none!important;color:#fff!important;border:0!important;isolation:isolate;min-height:212px!important;justify-content:flex-end!important;padding:24px 22px!important}
.svc.svc-img::before{display:none!important}
.svc-bg{position:absolute!important;inset:0;z-index:-2;border-radius:20px;overflow:hidden}
.svc-bg img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s ease}
.svc.svc-img:hover .svc-bg img{transform:scale(1.06)}
.svc.svc-img::after{content:"";position:absolute;inset:0;z-index:-1;border-radius:20px;background:linear-gradient(180deg,rgba(5,8,20,.06) 0%,rgba(5,8,20,.20) 28%,rgba(5,8,20,.50) 48%,rgba(5,8,20,.80) 68%,rgba(5,8,20,.94) 100%)}
.svc.svc-img .si{background:rgba(8,10,20,.42)!important;border:1px solid rgba(255,255,255,.16)!important;color:#fff!important}
.svc.svc-img b{color:#fff!important;text-shadow:0 1px 10px rgba(5,8,20,.55)}
.svc.svc-img span{color:rgba(255,255,255,.96)!important;text-shadow:0 1px 8px rgba(5,8,20,.5)}
.svc.svc-img .go{color:#fff!important;text-shadow:0 1px 8px rgba(5,8,20,.5)}
.svc.svc-img .svc-copy{display:flex;flex-direction:column;gap:6px;align-self:flex-start;position:relative;z-index:1;max-width:100%;margin:0 -4px -2px;padding:12px 15px 13px;border-radius:13px;background:linear-gradient(100deg,rgba(5,8,20,.9) 0%,rgba(5,8,20,.76) 60%,rgba(5,8,20,.24) 100%);backdrop-filter:blur(2px)}
.svc.svc-img .svc-copy .go{margin-top:4px}
.svc.svc-img .svc-copy b,.svc.svc-img .svc-copy span{text-shadow:0 1px 6px rgba(5,8,20,.45)}
.svc.svc-cta{background:linear-gradient(135deg,#0B1030,#1B2140 55%,#2A356E)!important;color:#fff!important;border:0!important;min-height:212px!important;justify-content:flex-end!important}
.svc.svc-cta::before{background:var(--amber)!important}
.svc.svc-cta .si{background:rgba(255,255,255,.14)!important;color:#FFD36A!important}
.svc.svc-cta b{color:#fff!important}
.svc.svc-cta span{color:rgba(255,255,255,.82)!important}
.svc.svc-cta .go{color:#FFD36A!important}



#enquiry [hidden]{display:none!important}
#enquiry .msform{position:relative}
#enquiry .ms-prog{margin:2px 0 20px}
#enquiry .ms-prog-top{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:8px}
#enquiry .ms-step-label{font-family:var(--sans);font-size:.74rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--cobalt)}
#enquiry .ms-step-label b{color:var(--cobalt)}
#enquiry .ms-step-name{font-family:var(--sans);font-size:.8rem;font-weight:600;color:var(--muted)}
#enquiry .ms-bar{height:6px;border-radius:6px;background:var(--stone);overflow:hidden}
#enquiry .ms-bar i{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,var(--cobalt),var(--violet,#8057F5));transition:width .35s ease}
#enquiry .ms-step{display:none;animation:msfade .3s ease}
#enquiry .ms-step.is-active{display:block}
@keyframes msfade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
#enquiry .ms-h{font-family:var(--serif,Playfair Display,serif);font-size:1.35rem;margin:0 0 4px;color:var(--ink)}
#enquiry .ms-sub{font-family:var(--sans);font-size:.9rem;color:var(--muted);margin:0 0 16px}
#enquiry .ms-multi{font-weight:500;font-size:.72rem;text-transform:none;letter-spacing:0;color:var(--muted);margin-left:6px}
#enquiry .ms-cards{display:grid;grid-template-columns:1fr 1fr;gap:10px}
#enquiry .ms-cards.one{grid-template-columns:1fr}
#enquiry .ms-card{display:block;position:relative;border:1.5px solid var(--line);border-radius:12px;padding:12px 13px 12px 40px;cursor:pointer;background:var(--paper);transition:.18s}
#enquiry .ms-card:hover{border-color:var(--cobalt)}
#enquiry .ms-card input{position:absolute;left:13px;top:14px;width:17px;height:17px;accent-color:var(--cobalt);margin:0}
#enquiry .ms-card .ms-card-t{display:block;font-family:var(--sans);font-weight:700;font-size:.86rem;color:var(--ink)}
#enquiry .ms-card .ms-card-d{display:block;font-family:var(--sans);font-size:.76rem;line-height:1.45;color:var(--muted);margin-top:3px}
#enquiry .ms-card.is-on{border-color:var(--cobalt);background:var(--sky,#EAF1FF)}
#enquiry .ms-nav{display:flex;gap:12px;align-items:center;margin-top:22px}
#enquiry .ms-nav .btn{cursor:pointer}
#enquiry .ms-prev{background:transparent;border:1.5px solid var(--line);color:var(--ink)}
#enquiry .ms-prev:hover{border-color:var(--ink)}
#enquiry .ms-next,#enquiry .ms-submit{margin-left:auto}
#enquiry .ms-err{border-color:var(--clay)!important;box-shadow:0 0 0 3px rgba(255,70,103,.14)}
#enquiry .ms-errmsg{color:var(--clay);font-size:.78rem;font-family:var(--sans);margin:6px 0 0;display:none}
#enquiry .ms-errmsg.show{display:block}
#enquiry .ms-files{margin-top:10px;display:flex;flex-wrap:wrap;gap:10px}
#enquiry .ms-thumb{position:relative;width:74px;height:74px;border-radius:10px;overflow:hidden;border:1px solid var(--line)}
#enquiry .ms-thumb img{width:100%;height:100%;object-fit:cover;display:block}
#enquiry .ms-thumb button{position:absolute;top:2px;right:2px;width:20px;height:20px;border:none;border-radius:50%;background:rgba(9,13,24,.78);color:#fff;font-size:13px;line-height:20px;cursor:pointer;padding:0}
#enquiry .ms-agree{font-family:var(--sans);font-size:.76rem;color:var(--muted);line-height:1.5;background:var(--sky,#EAF1FF);border-radius:12px;padding:12px 14px;margin:18px 0 4px}
#enquiry .ms-agree ul{margin:6px 0 0;padding-left:18px}
#enquiry .ms-agree li{margin:2px 0}
#enquiry .ms-help{font-family:var(--sans);font-size:.75rem;color:var(--muted);margin:6px 0 0}
#enquiry .ms-done{text-align:center;padding:24px 8px}
#enquiry .ms-done h3{font-family:var(--serif,Playfair Display,serif);color:var(--ink);font-size:1.5rem;margin:0 0 8px}
#enquiry .ms-done p{color:var(--muted);font-family:var(--sans);max-width:44ch;margin:0 auto}
#enquiry .ms-done svg{width:52px;height:52px;color:var(--teal,#0CA899);margin-bottom:10px}
@media(max-width:560px){#enquiry .ms-cards{grid-template-columns:1fr}#enquiry .ms-nav{flex-wrap:wrap}#enquiry .ms-next,#enquiry .ms-submit,#enquiry .ms-prev{width:100%;margin-left:0}#enquiry .ms-prog-top{flex-direction:column;gap:2px}}

:root{
  --black:#111213; --ink:#191A1B; --ivory:#F7F3EC; --paper:#FCFAF5; --stone:#D8CFC2;
  --bronze:#B88A55; --bronze-d:#8A6236; --taupe:#9C8875; --clay:#A96658;
  --muted:#6b6157; --line:rgba(17,18,19,.12); --line-soft:rgba(17,18,19,.07);
  --shadow:0 24px 60px rgba(17,18,19,.14); --shadow-sm:0 12px 30px rgba(17,18,19,.08);
  --gut:clamp(18px,5vw,68px); --maxw:1240px; --radius:4px;
  --serif:"Playfair Display",Georgia,"Times New Roman",serif;
  --sans:"Montserrat",-apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;
  --script:"Dancing Script","Playfair Display",cursive;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);color:var(--ink);background:var(--ivory);
  font-size:16px;line-height:1.68;font-weight:400;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--serif);font-weight:600;line-height:1.08;margin:0;letter-spacing:.4px}
p{margin:0 0 1em}
svg{width:20px;height:20px;flex-shrink:0}
.wrap{max-width:var(--maxw);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.eyebrow{font-family:var(--sans);font-weight:700;font-size:.7rem;letter-spacing:.28em;
  text-transform:uppercase;color:var(--bronze-d);margin:0 0 18px}
.script{font-family:var(--script);color:var(--bronze-d);font-weight:400}
.section{padding:clamp(58px,8vw,110px) 0}
.center{text-align:center}
.lead{font-size:clamp(1.02rem,1.35vw,1.16rem);color:var(--muted);max-width:60ch}
.center .lead{margin-left:auto;margin-right:auto}
.skip{position:absolute;left:-999px;top:0;background:var(--black);color:var(--ivory);padding:10px 16px;z-index:200}
.skip:focus{left:0}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,
label:focus-visible,summary:focus-visible{outline:2px solid var(--bronze-d);outline-offset:3px}
/* buttons */
.btn{display:inline-flex;align-items:center;gap:.55em;font-family:var(--sans);font-weight:600;
  font-size:.8rem;letter-spacing:.1em;text-transform:uppercase;padding:15px 28px;border-radius:var(--radius);
  border:1.5px solid var(--black);cursor:pointer;transition:.25s ease;line-height:1.1;text-align:center}
.btn svg{width:16px;height:16px}
.btn-p{background:var(--black);color:var(--ivory);border-color:var(--black)}
.btn-p:hover{background:var(--bronze);border-color:var(--bronze);color:var(--black)}
.btn-o{background:transparent;color:var(--ink);border-color:var(--black)}
.btn-o:hover{background:var(--black);color:var(--ivory)}
.btn-l{background:transparent;color:var(--ivory);border-color:rgba(247,243,236,.5)}
.btn-l:hover{background:var(--ivory);color:var(--black);border-color:var(--ivory)}
.btn-br{background:var(--bronze);color:var(--black);border-color:var(--bronze)}
.btn-br:hover{background:var(--black);color:var(--ivory);border-color:var(--black)}
/* utility bar */
.util{background:var(--black);color:var(--stone);font-size:.72rem;letter-spacing:.12em}
.util .wrap{display:flex;justify-content:space-between;align-items:center;gap:14px;min-height:38px;
  padding-top:9px;padding-bottom:9px}
.util .u-desc{text-transform:uppercase;font-weight:600}
.util .u-r{display:flex;gap:22px;align-items:center}
.util a{color:var(--ivory)}
.util .u-link{display:inline-flex;align-items:center;gap:7px;font-weight:600}
.util .u-link svg{width:13px;height:13px;color:var(--bronze)}
@media(max-width:720px){.util .u-desc{display:none}}
/* header */
.hdr{position:sticky;top:0;z-index:120;background:rgba(247,243,236,.9);
  backdrop-filter:saturate(140%) blur(9px);border-bottom:1px solid var(--line-soft);transition:box-shadow .3s,background .3s}
.hdr-in{max-width:var(--maxw);margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;gap:20px;min-height:80px}
.logo{display:flex;align-items:center;flex:0 0 auto}
.logo img{height:42px;width:auto}
#navtog{position:absolute;opacity:0;width:1px;height:1px;pointer-events:none}
.burger{display:none;margin-left:auto;flex-direction:column;gap:5px;cursor:pointer;padding:11px;border:1px solid var(--line);border-radius:4px}
.burger span{width:22px;height:2px;background:var(--black);display:block;transition:.25s}
.nav{margin-left:auto;display:flex;align-items:center;gap:4px}
.ni{position:relative}
.nlk{display:inline-flex;align-items:center;gap:5px;font-weight:600;font-size:.78rem;letter-spacing:.06em;
  text-transform:uppercase;padding:12px 13px;border-radius:4px;color:var(--ink)}
.nlk:hover{color:var(--bronze-d)}
.ni .caret{width:11px;height:11px;transition:transform .2s;opacity:.6}
.has-drop:hover .caret,.has-drop:focus-within .caret{transform:rotate(180deg)}
.mega{position:absolute;top:calc(100% + 6px);left:0;min-width:258px;background:var(--paper);
  border:1px solid var(--line-soft);box-shadow:var(--shadow-sm);padding:10px;opacity:0;visibility:hidden;
  transform:translateY(8px);transition:.2s ease;z-index:130;border-radius:4px}
.has-drop:hover .mega,.has-drop:focus-within .mega{opacity:1;visibility:visible;transform:translateY(0)}
.mega a{display:block;padding:9px 12px;font-size:.82rem;font-weight:500;color:var(--ink);letter-spacing:.01em}
.mega a:hover{background:var(--ivory);color:var(--bronze-d)}
.mega .mh{font-family:var(--sans);font-size:.62rem;letter-spacing:.2em;text-transform:uppercase;color:var(--bronze-d);padding:8px 12px 4px;font-weight:700}
.hdr-cta{margin-left:8px;flex:0 0 auto;padding:12px 20px;font-size:.72rem}
.hdr.stuck{box-shadow:0 10px 30px rgba(17,18,19,.08);background:rgba(247,243,236,.98)}
@media(max-width:1200px){
  .burger{display:flex}
  .nav{position:fixed;top:0;right:0;height:100vh;width:min(370px,86vw);background:var(--paper);margin:0;
    flex-direction:column;align-items:stretch;gap:0;padding:96px 24px 40px;box-shadow:-20px 0 50px rgba(17,18,19,.18);
    overflow-y:auto;clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .3s ease}
  #navtog:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
  #navtog:checked ~ .burger span:nth-child(1){transform:translateY(7px) rotate(45deg)}
  #navtog:checked ~ .burger span:nth-child(2){opacity:0}
  #navtog:checked ~ .burger span:nth-child(3){transform:translateY(-7px) rotate(-45deg)}
  .nlk{padding:14px 6px;font-size:.82rem;border-bottom:1px solid var(--line-soft);border-radius:0;width:100%}
  .ni{width:100%}.ni .caret{display:none}
  .mega{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:none;background:transparent;padding:2px 0 8px 8px;min-width:0}
  .mega a{padding:8px 10px;font-size:.85rem;text-transform:none}
  .hdr-cta{display:none}
  .nav .m-cta{display:inline-flex;justify-content:center;margin-top:18px}
}
@media(min-width:1201px){.nav .m-cta{display:none}}
/* hero */
.hero{background:var(--ivory);position:relative;overflow:hidden}
.hero-grid{display:grid;grid-template-columns:1.02fr 1.1fr;gap:clamp(30px,4.5vw,72px);align-items:center;
  padding-top:clamp(46px,6vw,84px);padding-bottom:clamp(46px,6vw,84px)}
.hero h1{font-size:clamp(2.5rem,5.6vw,4.4rem);letter-spacing:.5px;margin:2px 0 6px;font-weight:600}
.hero h1 .em{font-style:italic;color:var(--bronze-d);font-weight:500}
.hero .h-script{font-family:var(--script);color:var(--bronze-d);font-size:clamp(1.7rem,3vw,2.5rem);
  font-weight:400;margin:0 0 20px;line-height:1}
.hero-lead{font-size:clamp(1.05rem,1.5vw,1.2rem);color:var(--ink);max-width:46ch;margin-bottom:28px}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:26px}
.hero-tags{display:flex;flex-wrap:wrap;gap:9px}
.hero-tags a{font-size:.72rem;font-weight:600;letter-spacing:.04em;color:var(--ink);border:1px solid var(--line);
  padding:8px 14px;border-radius:40px;background:var(--paper);text-transform:uppercase}
.hero-tags a:hover{border-color:var(--bronze);color:var(--bronze-d)}
/* hero collage */
.collage{position:relative;display:grid;grid-template-columns:1.5fr 1fr;grid-template-rows:auto auto;
  gap:16px;align-items:stretch}
.collage .big{grid-row:1 / span 2;position:relative;border-radius:4px;overflow:hidden;box-shadow:var(--shadow)}
.collage .big img{width:100%;height:100%;object-fit:cover;aspect-ratio:3/4}
.collage .sm{position:relative;border-radius:4px;overflow:hidden;box-shadow:var(--shadow-sm)}
.collage .sm img{width:100%;height:100%;object-fit:cover;aspect-ratio:4/3}
.rec{position:absolute;top:14px;left:14px;display:inline-flex;align-items:center;gap:7px;background:rgba(17,18,19,.72);
  color:var(--ivory);font-family:var(--sans);font-size:.66rem;font-weight:600;letter-spacing:.14em;
  padding:6px 10px;border-radius:3px;backdrop-filter:blur(3px)}
.rec .dot{width:8px;height:8px;border-radius:50%;background:var(--clay);box-shadow:0 0 0 0 rgba(169,102,88,.6);animation:rec 1.6s infinite}
@keyframes rec{0%{box-shadow:0 0 0 0 rgba(169,102,88,.55)}70%{box-shadow:0 0 0 7px rgba(169,102,88,0)}100%{box-shadow:0 0 0 0 rgba(169,102,88,0)}}
.collage .fc{position:absolute;width:30px;height:30px;border:2px solid var(--bronze);z-index:3}
.collage .fc.tl{top:-9px;left:-9px;border-right:0;border-bottom:0}
.collage .fc.br{bottom:-9px;right:-9px;border-left:0;border-top:0}
@media(max-width:900px){.hero-grid{grid-template-columns:1fr;gap:36px}.collage{order:-1}}
@media(max-width:460px){.collage{grid-template-columns:1fr 1fr}.collage .big{grid-row:auto;grid-column:1 / -1}
  .collage .big img{aspect-ratio:16/10}}
/* section head */
.shead{max-width:66ch}.center .shead{margin:0 auto}
.shead.center{max-width:820px;margin-left:auto!important;margin-right:auto!important;text-align:center}
.shead.center .lead{margin-left:auto;margin-right:auto}
.shead .k{font-family:var(--sans);font-weight:700;font-size:.7rem;letter-spacing:.28em;text-transform:uppercase;color:var(--bronze-d);margin:0 0 14px}
.shead h2{font-size:clamp(2rem,3.8vw,3.1rem);margin:0 0 14px;font-weight:600}
.rule{width:46px;height:2px;background:var(--bronze);margin:16px 0 0}
.center .rule{margin-left:auto;margin-right:auto}
/* service strip (dark) */
.strip{background:var(--black);color:var(--ivory)}
.strip .wrap{padding-top:0;padding-bottom:0}
.strip-grid{display:grid;grid-template-columns:repeat(6,1fr)}
.svc{padding:38px 22px;border-right:1px solid rgba(247,243,236,.1);display:flex;flex-direction:column;gap:10px;transition:.25s;position:relative}
.svc:last-child{border-right:0}
.svc:hover{background:rgba(184,138,85,.1)}
.svc .si{width:34px;height:34px;color:var(--bronze)}
.svc .si svg{width:34px;height:34px}
.svc b{font-family:var(--serif);font-weight:600;font-size:1.32rem;color:var(--ivory);letter-spacing:.3px}
.svc span{font-size:.82rem;color:rgba(247,243,236,.66);line-height:1.45}
.svc .go{margin-top:auto;color:var(--bronze);font-size:.68rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;
  display:inline-flex;align-items:center;gap:6px;padding-top:10px}
.svc .go svg{width:13px;height:13px}
@media(max-width:1080px){.strip-grid{grid-template-columns:repeat(3,1fr)}
  .svc:nth-child(3){border-right:0}.svc:nth-child(n+4){border-top:1px solid rgba(247,243,236,.1)}}
@media(max-width:640px){.strip-grid{grid-template-columns:repeat(2,1fr)}
  .svc{border-right:1px solid rgba(247,243,236,.1)!important;border-top:1px solid rgba(247,243,236,.1)}
  .svc:nth-child(odd){border-left:0}.svc:nth-child(even){border-right:0!important}}
@media(max-width:430px){.svc{padding:26px 15px}.svc b{font-size:1.12rem;overflow-wrap:anywhere}.svc span{font-size:.78rem}}
/* specialist grid */
.spec-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:46px}
.spec{display:flex;flex-direction:column;gap:6px;padding:24px 22px;border:1px solid var(--line-soft);
  border-radius:4px;background:var(--paper);transition:.22s}
.spec:hover{border-color:var(--bronze);transform:translateY(-3px);box-shadow:var(--shadow-sm)}
.spec .ic{width:36px;height:36px;color:var(--bronze-d);margin-bottom:8px}
.spec .ic svg{width:26px;height:26px}
.spec b{font-family:var(--serif);font-weight:600;font-size:1.18rem;letter-spacing:.3px}
.spec span{font-size:.79rem;color:var(--muted)}
@media(max-width:900px){.spec-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:460px){.spec-grid{grid-template-columns:1fr}}
/* contact sheet */
.sheet{background:var(--paper);border-top:1px solid var(--line-soft);border-bottom:1px solid var(--line-soft)}
.cs-grid{display:grid;grid-template-columns:repeat(6,1fr);grid-auto-rows:150px;gap:14px;margin-top:48px}
.cs{position:relative;border-radius:4px;overflow:hidden;box-shadow:var(--shadow-sm)}
.cs img{width:100%;height:100%;object-fit:cover}
.cs .cap{position:absolute;left:0;bottom:0;right:0;padding:14px;background:linear-gradient(to top,rgba(17,18,19,.68),transparent);
  color:var(--ivory);font-family:var(--serif);font-weight:600;font-size:1rem;letter-spacing:.3px}
.cs .fn{position:absolute;top:10px;left:12px;font-family:var(--sans);font-size:.6rem;font-weight:600;letter-spacing:.14em;
  color:rgba(247,243,236,.85);background:rgba(17,18,19,.4);padding:3px 7px;border-radius:2px}
.cs-a{grid-column:span 2;grid-row:span 3}
.cs-b{grid-column:span 4;grid-row:span 2}
.cs-c{grid-column:span 3;grid-row:span 2}
.cs-d{grid-column:span 3;grid-row:span 3}
.cs-e{grid-column:span 2;grid-row:span 2}
.cs-f{grid-column:span 4;grid-row:span 2}
@media(max-width:820px){.cs-grid{grid-template-columns:repeat(2,1fr);grid-auto-rows:140px}
  .cs-a,.cs-b,.cs-c,.cs-d,.cs-e,.cs-f{grid-column:span 1;grid-row:span 2}
  .cs-a,.cs-d{grid-row:span 3}}
/* events */
.ev-grid{display:grid;grid-template-columns:repeat(12,1fr);grid-template-rows:clamp(300px,25vw,360px) clamp(240px,20vw,290px);gap:18px;margin-top:46px}
.ev{position:relative;border-radius:4px;overflow:hidden;box-shadow:var(--shadow-sm);grid-column:span 4;height:100%;display:block}
.ev img{width:100%;height:100%;object-fit:cover;transition:.5s}
.ev:hover img{transform:scale(1.05)}
.ev .ov{position:absolute;inset:0;background:linear-gradient(to top,rgba(17,18,19,.74),rgba(17,18,19,.04) 62%);
  display:flex;flex-direction:column;justify-content:flex-end;padding:22px}
.ev .ov b{font-family:var(--serif);font-weight:600;color:var(--ivory);font-size:1.34rem;letter-spacing:.3px}
.ev .ov span{color:var(--stone);font-size:.78rem;font-weight:500;display:inline-flex;align-items:center;gap:6px;text-transform:uppercase;letter-spacing:.06em}
.ev .ov span svg{width:13px;height:13px;color:var(--bronze)}
.ev-lg{grid-column:span 8}
@media(max-width:820px){.ev-grid{grid-template-columns:repeat(2,1fr);grid-template-rows:none;grid-auto-rows:clamp(200px,32vw,250px)}.ev{grid-column:span 1}.ev-lg{grid-column:span 2}}
@media(max-width:520px){.ev-grid{grid-template-columns:1fr;grid-template-rows:none;grid-auto-rows:clamp(190px,56vw,240px)}.ev-lg{grid-column:span 1}.ev{grid-column:span 1}}
/* locations */
.loc{background:var(--black);color:var(--ivory)}
.loc .k{color:var(--bronze)}
.loc h2{color:var(--ivory)}
.loc .lead{color:rgba(247,243,236,.76)}
.loc .rule{background:var(--bronze)}
.state-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:46px}
.state{display:block;padding:26px 22px;border:1px solid rgba(247,243,236,.15);border-radius:4px;background:rgba(247,243,236,.03);transition:.24s}
.state:hover{background:rgba(184,138,85,.1);border-color:var(--bronze);transform:translateY(-3px)}
.state b{font-family:var(--serif);font-weight:600;font-size:1.32rem;display:block;margin-bottom:6px;letter-spacing:.3px}
.state span{font-size:.8rem;color:rgba(247,243,236,.6)}
.state .arw{margin-top:14px;display:inline-flex;align-items:center;gap:7px;color:var(--bronze);font-weight:700;font-size:.68rem;letter-spacing:.12em;text-transform:uppercase}
.chips{margin-top:34px;display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.chips .cl{font-size:.66rem;letter-spacing:.2em;text-transform:uppercase;color:var(--stone);margin-right:6px;font-weight:700}
.chip{font-size:.8rem;font-weight:500;color:var(--ivory);border:1px solid rgba(247,243,236,.22);padding:8px 15px;border-radius:40px;transition:.2s}
.chip:hover{border-color:var(--bronze);color:var(--bronze)}
@media(max-width:900px){.state-grid{grid-template-columns:1fr 1fr}}
@media(max-width:460px){.state-grid{grid-template-columns:1fr}}
/* steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-top:50px}
.step{padding:28px 24px;border-radius:4px;background:var(--paper);border:1px solid var(--line-soft);position:relative}
.step .n{font-family:var(--serif);font-size:2.4rem;font-weight:600;color:var(--bronze);line-height:1;margin-bottom:14px}
.step h3{font-size:1.24rem;margin:0 0 8px;font-weight:600}
.step p{font-size:.86rem;color:var(--muted);margin:0}
@media(max-width:880px){.steps{grid-template-columns:1fr 1fr}}
@media(max-width:460px){.steps{grid-template-columns:1fr}}
/* more ways */
.more-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:44px}
.mcard{display:flex;gap:16px;padding:26px;border-radius:4px;background:var(--paper);border:1px solid var(--line-soft);transition:.24s}
.mcard:hover{border-color:var(--bronze);transform:translateY(-3px)}
.mcard .mi{width:42px;height:42px;flex:0 0 auto;color:var(--bronze-d)}
.mcard .mi svg{width:32px;height:32px}
.mcard b{font-family:var(--serif);font-weight:600;font-size:1.18rem;display:block;margin-bottom:5px;letter-spacing:.3px}
.mcard p{font-size:.84rem;color:var(--muted);margin:0 0 10px}
.mcard .go{font-weight:700;font-size:.68rem;letter-spacing:.12em;text-transform:uppercase;color:var(--bronze-d);display:inline-flex;align-items:center;gap:6px}
.mcard .go svg{width:13px;height:13px}
@media(max-width:860px){.more-grid{grid-template-columns:1fr}}
/* about */
.about-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:clamp(30px,4.5vw,64px);align-items:center}
.about-media{position:relative}
.about-media img{border-radius:4px;box-shadow:var(--shadow);aspect-ratio:5/4;object-fit:cover;width:100%}
.about-media .fc{position:absolute;width:34px;height:34px;border:2px solid var(--bronze);z-index:2}
.about-media .fc.tl{top:-10px;left:-10px;border-right:0;border-bottom:0}
.about-media .fc.br{bottom:-10px;right:-10px;border-left:0;border-top:0}
.about-media .stamp{position:absolute;right:-16px;bottom:-16px;width:118px;height:118px;border-radius:50%;
  background:var(--black);color:var(--ivory);display:flex;flex-direction:column;align-items:center;justify-content:center;
  text-align:center;padding:12px;box-shadow:var(--shadow)}
.about-media .stamp b{font-family:var(--serif);color:var(--bronze);font-size:1.7rem;line-height:1;font-weight:600}
.about-media .stamp span{font-size:.56rem;letter-spacing:.14em;text-transform:uppercase;margin-top:5px;color:var(--stone)}
@media(max-width:820px){.about-grid{grid-template-columns:1fr}.about-media{max-width:440px}}
/* essence band */
.essence{background:var(--stone);color:var(--black);text-align:center}
.essence .fl{font-family:var(--sans);font-weight:700;font-size:.68rem;letter-spacing:.26em;text-transform:uppercase;color:var(--bronze-d);margin:0 0 20px}
.essence h2{font-size:clamp(2rem,4.4vw,3.4rem);max-width:20ch;margin:0 auto 20px;font-weight:600;line-height:1.12}
.essence h2 .em{font-style:italic;color:var(--bronze-d)}
.essence p{font-size:clamp(1rem,1.4vw,1.16rem);color:var(--ink);max-width:52ch;margin:0 auto}
/* enquiry */
.enq{background:var(--paper);border-top:1px solid var(--line-soft)}
.enq-grid{display:grid;grid-template-columns:.92fr 1.08fr;gap:clamp(30px,4vw,64px);align-items:start}
.enq-info .rule{background:var(--bronze)}
.enq-list{list-style:none;padding:0;margin:26px 0 0}
.enq-list li{display:flex;gap:12px;align-items:flex-start;margin-bottom:16px;font-size:.92rem;color:var(--ink)}
.enq-list li svg{width:20px;height:20px;color:var(--bronze-d);margin-top:2px}
.form{background:var(--ivory);border:1px solid var(--line-soft);border-radius:6px;padding:clamp(22px,3vw,36px)}
.form h3{font-size:1.5rem;margin:0 0 4px;font-weight:600}
.form .fnote{font-size:.82rem;color:var(--muted);margin:0 0 20px}
.frow{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.field{display:flex;flex-direction:column;gap:6px;margin-bottom:16px;min-width:0}
.field.full{grid-column:1/-1}
.field label{font-size:.74rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--ink)}
.field label .req{color:var(--clay)}
.field input,.field select,.field textarea{width:100%;min-width:0;font-family:var(--sans);font-size:.92rem;
  padding:12px 14px;border:1px solid var(--line);border-radius:4px;background:#fff;color:var(--ink)}
.field textarea{resize:vertical;min-height:96px}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--bronze-d);outline:none;box-shadow:0 0 0 3px rgba(138,98,54,.14)}
.form .submit{width:100%;justify-content:center;margin-top:6px;padding:16px}
.form .privacy{font-size:.72rem;color:var(--muted);margin:14px 0 0;line-height:1.5}
.form .privacy a{color:var(--bronze-d);text-decoration:underline}
@media(max-width:860px){.enq-grid{grid-template-columns:1fr}}
@media(max-width:520px){.frow{grid-template-columns:1fr}}
/* cta band */
.cta{background:var(--black);color:var(--ivory);text-align:center;position:relative;overflow:hidden}
.cta .h-script{font-family:var(--script);color:var(--bronze);font-size:clamp(1.7rem,3.4vw,2.6rem);font-weight:400;margin:0 0 12px;line-height:1}
.cta h2{color:var(--ivory);font-size:clamp(2rem,4vw,3.1rem);margin:0 0 16px;font-weight:600}
.cta p{color:rgba(247,243,236,.78);max-width:54ch;margin:0 auto 30px}
.cta .row{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}
/* footer */
footer{background:var(--black);color:var(--stone);padding:66px 0 26px}
.f-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:36px;padding-bottom:44px;border-bottom:1px solid rgba(247,243,236,.12)}
.f-brand img{height:36px;margin-bottom:18px}
.f-brand .ftag{font-family:var(--script);color:var(--bronze);font-size:1.4rem;margin:0 0 12px;line-height:1;font-weight:400}
.f-brand .fdesc{font-size:.84rem;color:rgba(247,243,236,.6);max-width:34ch;margin:0 0 16px}
.f-brand .fmem{font-size:.76rem;color:rgba(247,243,236,.48)}
.f-brand .fmem b{color:var(--bronze);font-weight:600}
.fcol h4{font-family:var(--sans);font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;color:var(--bronze);margin:0 0 16px;font-weight:700}
.fcol a{display:block;font-size:.85rem;color:rgba(247,243,236,.76);padding:6px 0}
.fcol a:hover{color:var(--bronze)}
.f-bot{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;padding-top:24px}
.f-bot .legal{display:flex;gap:18px;flex-wrap:wrap;font-size:.78rem;align-items:center}
.f-bot .legal a{color:rgba(247,243,236,.58)}
.f-bot .legal a:hover{color:var(--bronze)}
.built{display:inline-flex;align-items:center;gap:9px;font-size:.78rem;color:rgba(247,243,236,.58)}
.built b{color:var(--bronze);font-weight:600}
.built-ico{width:26px;height:26px;border-radius:6px}
@media(max-width:860px){.f-top{grid-template-columns:1fr 1fr}.f-brand{grid-column:1/-1}}
@media(max-width:480px){.f-top{grid-template-columns:1fr}}
/* mobile bar */
.mbar{position:fixed;left:0;right:0;bottom:0;z-index:110;display:none;background:var(--black);border-top:1px solid rgba(247,243,236,.14);padding:10px 14px}
.mbar a{flex:1;justify-content:center;font-size:.72rem;padding:13px}
@media(max-width:1200px){.mbar{display:flex;gap:10px}body{padding-bottom:70px}}
/* reveal */
.rv{animation:rvIn .8s both}.rv.d1{animation-delay:.08s}.rv.d2{animation-delay:.16s}.rv.d3{animation-delay:.24s}
@keyframes rvIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}
  .rv{opacity:1!important;transform:none!important}.rec .dot{animation:none!important}}


/* =========================================================
   V4 BRAND GUIDELINE TYPOGRAPHY + EDITABLE IMAGE SLOTS
   Headings/Logo: Playfair Display
   Body/UI: Montserrat
   Accent/Script: Dancing Script
   ========================================================= */

/* Playfair reads best with slightly tighter display tracking. */
h1,h2,h3,h4{letter-spacing:-.015em}
.hero h1{letter-spacing:-.025em}
.svc b,.spec b,.ev .ov b,.state b,.step h3,.mcard b{letter-spacing:-.01em}
.hero .h-script,.cta .h-script,.f-brand .ftag,.script{font-weight:400;letter-spacing:0}

/* Specialist image cards */
.spec{padding:0;overflow:hidden;gap:0;background:#fff}
.spec-media{display:block;aspect-ratio:16/10;overflow:hidden;background:#e9e7ef}
.spec-media img{width:100%;height:100%;display:block;object-fit:cover;transition:transform .5s ease}
.spec:hover .spec-media img{transform:scale(1.055)}
.spec-copy{display:flex;flex-direction:column;gap:6px;padding:20px 20px 22px;min-height:168px}
.spec-copy .ic{margin-bottom:7px}

/* Location cards now have replaceable lifestyle photography. */
.state{padding:0;overflow:hidden;background:rgba(255,255,255,.06)}
.state-media{display:block;aspect-ratio:16/9;overflow:hidden;background:rgba(255,255,255,.08)}
.state-media img{width:100%;height:100%;display:block;object-fit:cover;filter:saturate(.92);transition:transform .55s ease,filter .3s ease}
.state:hover .state-media img{transform:scale(1.05);filter:saturate(1.08)}
.state-copy{display:block;padding:22px 22px 24px}
.state-copy>b,.state-copy>span{display:block}
.state-copy .arw{display:inline-flex}

/* Extra services use image-first cards rather than icon-only blocks. */
.mcard{padding:0;display:flex;flex-direction:column;gap:0;overflow:hidden}
.mcard-media{display:block;width:100%;aspect-ratio:16/9;overflow:hidden;background:#e9e7ef}
.mcard-media img{width:100%;height:100%;display:block;object-fit:cover;transition:transform .5s ease}
.mcard:hover .mcard-media img{transform:scale(1.05)}
.mcard-copy{display:grid;grid-template-columns:42px 1fr;gap:16px;padding:22px 24px 25px;align-items:start}
.mcard-copy>.mi{grid-column:1}
.mcard-copy>div{grid-column:2}

/* Optional replaceable photographic backgrounds. The image is applied only when a URL is added to IMAGE_LIBRARY. */
.editable-bg{position:relative;isolation:isolate;overflow:hidden}
.editable-bg::before{content:"";position:absolute;inset:0;background-image:var(--editable-bg-image,none);background-size:cover;background-position:center;opacity:var(--editable-bg-opacity,0);z-index:-2}
.editable-bg::after{content:"";position:absolute;inset:0;background:var(--editable-bg-overlay,transparent);z-index:-1;pointer-events:none}
.loc.editable-bg{--editable-bg-overlay:linear-gradient(90deg,rgba(20,34,110,.90),rgba(49,91,255,.84));--editable-bg-opacity:.30}
.essence.editable-bg{--editable-bg-overlay:linear-gradient(110deg,rgba(255,87,126,.92),rgba(128,87,245,.86));--editable-bg-opacity:.24}
.cta.editable-bg{--editable-bg-overlay:linear-gradient(110deg,rgba(10,12,24,.91),rgba(17,27,58,.88));--editable-bg-opacity:.34}

@media(max-width:900px){
  .spec-copy{min-height:0}
}



/* ==========================================================
   REEL THE MOMENT — V3 "CHROMATIC REEL"
   Direction: editorial photography + cinematic RGB/light-leak energy.
   Keeps the existing information architecture while breaking up the
   previous ivory/black/bronze repetition with intentional section tones.
   ========================================================== */
:root{
  --black:#090D18;
  --ink:#111526;
  --ivory:#FFF7EF;
  --paper:#FFFFFF;
  --stone:#E9EAF2;
  --bronze:#FF5F68;
  --bronze-d:#315BFF;
  --taupe:#73778A;
  --clay:#FF4667;
  --muted:#3F4557;
  --line:rgba(17,21,38,.12);
  --line-soft:rgba(17,21,38,.075);
  --shadow:0 28px 70px rgba(10,15,35,.18);
  --shadow-sm:0 14px 38px rgba(10,15,35,.10);
  --cobalt:#315BFF;
  --cyan:#11BFD4;
  --coral:#FF5F68;
  --amber:#FFBE38;
  --violet:#8057F5;
  --teal:#0CA899;
  --berry:#DD3E82;
  --sky:#EAF1FF;
  --lav:#F0EAFE;
  --mint:#E7FAF6;
  --peach:#FFF0E8;
  --butter:#FFF5CE;
}

body{background:#fff;color:var(--ink)}
.section{position:relative;overflow:hidden}
.wrap{max-width:1280px}
.eyebrow,.shead .k{color:var(--cobalt)}
.rule{background:linear-gradient(90deg,var(--cobalt),var(--coral),var(--amber));width:78px;height:4px;border-radius:10px}
.lead{color:var(--muted)}

/* Buttons */
.btn{border-radius:999px;padding:15px 26px;font-weight:800;letter-spacing:.08em;box-shadow:none}
.btn-p{background:var(--cobalt);border-color:var(--cobalt);color:#fff}
.btn-p:hover{background:#173FE5;border-color:#173FE5;color:#fff;transform:translateY(-2px)}
.btn-o{background:#fff;color:var(--ink);border-color:rgba(17,21,38,.20)}
.btn-o:hover{background:var(--ink);border-color:var(--ink);color:#fff;transform:translateY(-2px)}
.btn-br{background:var(--amber);color:var(--ink);border-color:var(--amber)}
.btn-br:hover{background:#fff;border-color:#fff;color:var(--ink);transform:translateY(-2px)}

/* Utility + header */
.util{background:linear-gradient(90deg,#315BFF 0%,#6F4CF6 48%,#E84786 100%);color:#fff}
.util a,.util .u-link svg{color:#fff}
.hdr{background:rgba(255,255,255,.90);border-bottom:1px solid rgba(17,21,38,.08);box-shadow:0 8px 30px rgba(18,24,50,.05)}
.hdr.stuck{background:rgba(255,255,255,.97);box-shadow:0 12px 36px rgba(18,24,50,.11)}
.nlk:hover{color:var(--cobalt)}
.mega{background:#fff;border-color:rgba(17,21,38,.08);border-radius:18px;box-shadow:0 24px 60px rgba(9,13,24,.15)}
.mega a:hover{background:var(--sky);color:var(--cobalt)}
.mega .mh{color:var(--cobalt)}
.burger{border-radius:12px}

/* HERO — dark cinematic stage with RGB/light-leak glows */
.hero{
  background:
    radial-gradient(circle at 88% 15%,rgba(255,82,112,.36),transparent 24%),
    radial-gradient(circle at 68% 85%,rgba(49,91,255,.42),transparent 28%),
    radial-gradient(circle at 12% 0%,rgba(128,87,245,.28),transparent 24%),
    linear-gradient(135deg,#080B14 0%,#111733 52%,#090D18 100%);
  color:#fff;
}
.hero::before{
  content:"";position:absolute;inset:0;pointer-events:none;opacity:.34;
  background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);
  background-size:42px 42px;
  mask-image:linear-gradient(to bottom,black,transparent 88%);
}
.hero::after{
  content:"";position:absolute;left:0;right:0;bottom:0;height:7px;
  background:linear-gradient(90deg,var(--cobalt) 0 20%,var(--cyan) 20% 37%,var(--amber) 37% 54%,var(--coral) 54% 73%,var(--violet) 73% 100%);
}
.hero-grid{position:relative;z-index:2;padding-top:clamp(64px,7vw,108px);padding-bottom:clamp(66px,7vw,108px)}
.hero .eyebrow{color:#9FDFFF;background:rgba(17,191,212,.12);border:1px solid rgba(17,191,212,.28);display:inline-flex;padding:8px 13px;border-radius:999px;letter-spacing:.2em}
.hero h1{color:#fff;font-size:clamp(3.05rem,4.35vw,4.35rem);line-height:.99;letter-spacing:-.025em;max-width:none}
.hero h1 .hb{display:block}
.hero h1 .em{
  background:linear-gradient(90deg,#FFD05A 0%,#FF6E7D 48%,#A87CFF 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent;font-style:italic;
}
.hero .h-script{color:#FFD46D;font-size:clamp(1.8rem,3vw,2.65rem)}
.hero-lead{color:rgba(255,255,255,.78);font-size:clamp(1.04rem,1.4vw,1.2rem)}
.hero .btn-p{background:var(--coral);border-color:var(--coral)}
.hero .btn-p:hover{background:#fff;border-color:#fff;color:var(--ink)}
.hero .btn-o{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.42);color:#fff;backdrop-filter:blur(8px)}
.hero .btn-o:hover{background:#fff;color:var(--ink);border-color:#fff}
.hero-tags a{background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.16);color:rgba(255,255,255,.82);backdrop-filter:blur(8px)}
.hero-tags a:hover{background:rgba(255,255,255,.14);border-color:#8DE6F1;color:#fff}
.collage{gap:18px;transform:rotate(-.7deg)}
.collage .big,.collage .sm{border-radius:22px;border:1px solid rgba(255,255,255,.17);box-shadow:0 30px 80px rgba(0,0,0,.38)}
.collage .sm:first-of-type{transform:translateY(18px) rotate(2deg)}
.collage .sm:last-of-type{transform:translateY(-4px) rotate(-2deg)}
.collage .fc{border-width:3px}
.collage .fc.tl{border-color:var(--cyan)}
.collage .fc.br{border-color:var(--coral)}
.rec{background:rgba(7,10,18,.75);border:1px solid rgba(255,255,255,.16);border-radius:999px}
.rec .dot{background:#FF385F}

/* COLOR DECK — service discovery */
.strip{background:#fff;color:var(--ink);padding:34px 0 48px}
.strip-grid{grid-template-columns:repeat(3,1fr);gap:14px}
.svc{border:0!important;border-radius:22px;padding:30px 28px;min-height:190px;color:#fff;box-shadow:0 16px 38px rgba(18,24,50,.10);overflow:hidden;isolation:isolate;transform:translateZ(0)}
.svc::before{content:"";position:absolute;width:130px;height:130px;border:26px solid rgba(255,255,255,.13);border-radius:50%;right:-40px;top:-48px;z-index:-1}
.svc::after{content:"";position:absolute;left:28px;right:28px;bottom:0;height:3px;background:rgba(255,255,255,.40);transform:scaleX(.22);transform-origin:left;transition:.28s}
.svc:hover{transform:translateY(-7px);box-shadow:0 25px 55px rgba(18,24,50,.17)}
.svc:hover::after{transform:scaleX(1)}
.svc:nth-child(1){background:linear-gradient(135deg,#2453FF,#4177FF)}
.svc:nth-child(2){background:linear-gradient(135deg,#7048EF,#9B61FF)}
.svc:nth-child(3){background:linear-gradient(135deg,#F94C72,#FF786D)}
.svc:nth-child(4){background:linear-gradient(135deg,#FFAE26,#FFD35E);color:#171521}
.svc:nth-child(5){background:linear-gradient(135deg,#009A92,#19C8B8)}
.svc:nth-child(6){background:linear-gradient(135deg,#121728,#252C46)}
.svc .si,.svc .go{color:inherit}
.svc b{font-size:1.55rem;color:inherit}
.svc span{color:inherit;opacity:.88}
.svc .go{opacity:1}
.svc:nth-child(4) .si,.svc:nth-child(4) .go{color:#171521}

/* Specialist directory — clean cards, chromatic tabs */
.specialist-zone{background:linear-gradient(180deg,#F6F8FF 0%,#FFFFFF 100%)}
.spec-grid{gap:18px}
.spec{position:relative;overflow:hidden;border:1px solid rgba(17,21,38,.08);border-radius:20px;background:#fff;padding:27px 24px 25px;box-shadow:0 10px 30px rgba(25,34,70,.055)}
.spec::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:var(--c,var(--cobalt))}
.spec:nth-child(1){--c:#FF5F68}.spec:nth-child(2){--c:#315BFF}.spec:nth-child(3){--c:#DD3E82}.spec:nth-child(4){--c:#0CA899}
.spec:nth-child(5){--c:#8057F5}.spec:nth-child(6){--c:#11BFD4}.spec:nth-child(7){--c:#FF9A30}.spec:nth-child(8){--c:#141A2C}
.spec .ic{color:var(--c)!important;background:color-mix(in srgb,var(--c) 11%,white);width:46px;height:46px;border-radius:14px;display:grid;place-items:center}
.spec:hover{border-color:color-mix(in srgb,var(--c) 45%,white);box-shadow:0 20px 42px color-mix(in srgb,var(--c) 13%,transparent);transform:translateY(-6px)}
.spec b{font-size:1.23rem}

/* Portfolio wall — almost black so imagery becomes the colour */
.gallery-zone{background:#090D18!important;border:0!important;color:#fff}
.gallery-zone::before{content:"";position:absolute;inset:auto -10% -40% 45%;height:65%;background:radial-gradient(circle,rgba(49,91,255,.20),transparent 65%);pointer-events:none}
.gallery-zone .shead .k{color:#7FE8F1}
.gallery-zone .shead h2{color:#fff}
.gallery-zone .lead{color:rgba(255,255,255,.68)}
.gallery-zone .rule{background:linear-gradient(90deg,var(--cyan),var(--coral),var(--amber))}
.gallery-zone .cs-grid{gap:16px}
.gallery-zone .cs{border-radius:18px;box-shadow:0 15px 40px rgba(0,0,0,.35);border:1px solid rgba(255,255,255,.12)}
.gallery-zone .cs img{transition:transform .55s ease,filter .55s ease;filter:saturate(1.03) contrast(1.02)}
.gallery-zone .cs:hover img{transform:scale(1.045);filter:saturate(1.18) contrast(1.04)}
.gallery-zone .cs:nth-child(1){box-shadow:0 0 0 2px rgba(255,95,104,.65),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(2){box-shadow:0 0 0 2px rgba(49,91,255,.70),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(3){box-shadow:0 0 0 2px rgba(128,87,245,.70),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(4){box-shadow:0 0 0 2px rgba(12,168,153,.68),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(5){box-shadow:0 0 0 2px rgba(255,190,56,.70),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .cs:nth-child(6){box-shadow:0 0 0 2px rgba(17,191,212,.68),0 18px 44px rgba(0,0,0,.34)}
.gallery-zone .btn-o{background:transparent;color:#fff;border-color:rgba(255,255,255,.35)}
.gallery-zone .btn-o:hover{background:#fff;color:var(--ink);border-color:#fff}

/* Events — warm gallery page */
.events-zone{background:linear-gradient(180deg,#FFF4EC 0%,#FFFDFC 100%)}
.events-zone .shead .k{color:#E54C76}
.ev-grid{gap:18px}
.ev{border-radius:24px;box-shadow:0 18px 45px rgba(45,24,20,.14)}
.ev::after{content:"";position:absolute;inset:0;border:2px solid transparent;border-radius:inherit;transition:.3s;pointer-events:none}
.ev:hover::after{border-color:rgba(255,255,255,.7);inset:9px}
.ev .ov{padding:26px;background:linear-gradient(to top,rgba(8,10,18,.85),rgba(8,10,18,.04) 67%)}
.ev .ov b{font-size:1.55rem}
.ev .ov span svg{color:#FFD36A}

/* Locations — electric blue geographic hub */
.loc{
  background:
    radial-gradient(circle at 14% 20%,rgba(17,191,212,.34),transparent 24%),
    radial-gradient(circle at 92% 90%,rgba(128,87,245,.40),transparent 26%),
    linear-gradient(135deg,#1747E8 0%,#315BFF 48%,#5535CC 100%);
  color:#fff;
}
.loc .k{color:#B8F4F7}
.loc h2{color:#fff}
.loc .lead{color:rgba(255,255,255,.78)}
.loc .rule{background:linear-gradient(90deg,#86F0F6,#FFD768,#FF8BA0)}
.state-grid{gap:14px}
.state{border-color:rgba(255,255,255,.22);border-radius:20px;background:rgba(255,255,255,.10);backdrop-filter:blur(8px);padding:29px 24px}
.state:hover{background:#fff;color:var(--ink);border-color:#fff;transform:translateY(-6px);box-shadow:0 22px 45px rgba(15,28,82,.23)}
.state:hover span{color:var(--muted)}
.state:hover .arw{color:var(--cobalt)}
.state .arw{color:#FFF0A9}
.chip{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.25);color:#fff}
.chip:hover{background:#fff;color:var(--cobalt);border-color:#fff}

/* How it works — playful film/contact-sheet numbering */
.how-zone{background:var(--butter)}
.how-zone .shead .k{color:#9A6D00}
.steps{gap:16px}
.step{border:0;border-radius:22px;background:#fff;padding:31px 25px;box-shadow:0 12px 34px rgba(80,65,15,.08);overflow:hidden}
.step::after{content:"";position:absolute;right:-30px;top:-30px;width:92px;height:92px;border-radius:50%;background:var(--step-color);opacity:.10}
.step:nth-child(1){--step-color:#315BFF}.step:nth-child(2){--step-color:#8057F5}.step:nth-child(3){--step-color:#FF5F68}.step:nth-child(4){--step-color:#0CA899}
.step .n{display:grid;place-items:center;width:54px;height:54px;border-radius:16px;background:var(--step-color);color:#fff;font-family:var(--sans);font-size:1.25rem;font-weight:800}
.step h3{margin-top:18px}

/* More ways — mint content-creator panel */
.more-zone{background:var(--mint)!important;border:0!important}
.more-zone .shead .k{color:#087A70}
.mcard{border:1px solid rgba(17,21,38,.08);border-radius:22px;background:#fff;padding:28px;box-shadow:0 12px 32px rgba(7,92,82,.07)}
.mcard:nth-child(1){--mc:#315BFF}.mcard:nth-child(2){--mc:#DD3E82}.mcard:nth-child(3){--mc:#FF9A30}
.mcard .mi{color:var(--mc);background:color-mix(in srgb,var(--mc) 11%,white);border-radius:15px;display:grid;place-items:center;width:54px;height:54px}
.mcard .go{color:var(--mc)}
.mcard:hover{border-color:color-mix(in srgb,var(--mc) 40%,white);box-shadow:0 18px 44px color-mix(in srgb,var(--mc) 12%,transparent);transform:translateY(-6px)}

/* About — clean editorial reset with a bold image frame */
.about-zone{background:#fff}
.about-zone::after{content:"";position:absolute;right:-100px;top:55px;width:310px;height:310px;border-radius:50%;background:radial-gradient(circle,rgba(255,95,104,.13),transparent 68%);pointer-events:none}
.about-media img{border-radius:26px;box-shadow:0 24px 60px rgba(19,24,50,.16)}
.about-media .fc{border-width:4px}.about-media .fc.tl{border-color:var(--cobalt)}.about-media .fc.br{border-color:var(--coral)}
.about-media .stamp{background:linear-gradient(145deg,#8057F5,#315BFF);color:#fff;width:132px;height:132px;border:5px solid #fff}
.about-media .stamp b{color:#FFD86E}
.about-zone .about-copy .k{color:var(--cobalt)!important}
.about-zone .about-copy h2 span{color:var(--coral)!important}

/* Brand essence — a photographic light leak instead of a flat beige band */
.essence{
  background:
    radial-gradient(circle at 18% 30%,rgba(255,255,255,.34),transparent 20%),
    radial-gradient(circle at 82% 60%,rgba(128,87,245,.36),transparent 25%),
    linear-gradient(120deg,#FFB439 0%,#FF7069 42%,#E8438B 70%,#7C59F6 100%);
  color:#111526;
}
.essence .fl{color:#111526;background:rgba(255,255,255,.42);display:inline-flex;padding:7px 12px;border-radius:999px}
.essence h2{max-width:23ch;color:#111526}
.essence h2 .em{color:#fff;text-shadow:0 2px 20px rgba(72,20,79,.18)}
.essence p{color:rgba(17,21,38,.82)}

/* Enquiry — soft chromatic background, bright white form */
.enq{background:linear-gradient(135deg,#EEF3FF 0%,#F3EAFF 48%,#E8FAF5 100%);border:0}
.enq::before{content:"";position:absolute;left:-80px;bottom:-100px;width:260px;height:260px;border-radius:50%;background:radial-gradient(circle,rgba(17,191,212,.16),transparent 68%)}
.enq .enq-info .k{color:var(--cobalt)!important}
.enq-list li svg{color:var(--teal)}
.form{position:relative;overflow:hidden;background:#fff;border:1px solid rgba(17,21,38,.08);border-radius:24px;padding:clamp(26px,3vw,40px);box-shadow:0 28px 70px rgba(40,50,100,.13)}
.form::before{content:"";position:absolute;left:0;right:0;top:0;height:7px;background:linear-gradient(90deg,var(--cobalt),var(--cyan),var(--amber),var(--coral),var(--violet))}
.field input,.field select,.field textarea{border-radius:12px;background:#FAFBFE;border-color:rgba(17,21,38,.12);padding:13px 14px}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--cobalt);box-shadow:0 0 0 4px rgba(49,91,255,.12)}
.form .privacy a{color:var(--cobalt)}

/* Final CTA — second cinematic scene, not a repeat of footer black */
.cta{
  background:
    radial-gradient(circle at 16% 0%,rgba(17,191,212,.30),transparent 25%),
    radial-gradient(circle at 84% 100%,rgba(255,70,103,.36),transparent 27%),
    linear-gradient(130deg,#0B1022 0%,#172254 45%,#351A63 100%);
  color:#fff;
}
.cta .h-script{color:#FFD369}
.cta h2{color:#fff}
.cta p{color:rgba(255,255,255,.77)}
.cta .btn-br{background:var(--coral);border-color:var(--coral);color:#fff}
.cta .btn-br:hover{background:#fff;border-color:#fff;color:var(--ink)}

/* Footer remains the visual anchor */
footer{background:#080B13;color:#D9DCE8}
.f-brand .ftag,.fcol h4,.f-brand .fmem b,.built b{color:#FFD369}
.fcol a:hover,.f-bot .legal a:hover{color:#8DE8F0}
.mbar{background:#080B13}

/* Motion/details */
.svc,.spec,.state,.step,.mcard,.ev,.btn{transition:transform .28s ease,box-shadow .28s ease,border-color .28s ease,background .28s ease,color .28s ease}

/* Responsive */
@media(max-width:1080px){
  .strip-grid{grid-template-columns:repeat(2,1fr)}
  .svc{border:0!important}
}
@media(max-width:900px){
  .hero h1{max-width:none}
  .collage{transform:none;order:-1}
  .about-zone::after{display:none}
}
@media(max-width:640px){
  .strip{padding:22px 0 34px}
  .strip-grid{grid-template-columns:1fr;gap:10px}
  .svc{min-height:155px;padding:25px 22px}
  .svc b{font-size:1.38rem}
  .hero-grid{padding-top:38px;padding-bottom:58px}
  .hero h1{font-size:clamp(1.9rem,10vw,2.6rem)}
  .hero .eyebrow{font-size:.62rem}
  .state,.step,.mcard,.spec{border-radius:18px}
}
@media(prefers-reduced-motion:reduce){.svc:hover,.spec:hover,.state:hover,.mcard:hover,.btn:hover{transform:none!important}}



/* ---- Brand-brief typography tuning (Playfair Display) ---- */
h1,h2,h3,h4{font-weight:600}
.hero h1{font-weight:600;letter-spacing:-.01em;line-height:1.0}
.essence h2,.cta h2,.shead h2{font-weight:600}
.svc b,.spec b,.ev .ov b,.state b{font-weight:600}
.h-script,.ftag,.script{font-weight:600}

/* ---- HERO: balance the stage, reduce empty space ---- */
.hero-grid{gap:clamp(28px,3vw,52px);align-items:center;
  padding-top:clamp(34px,3.6vw,60px);padding-bottom:clamp(44px,5vw,80px)}
@media(min-width:901px){.hero-grid{grid-template-columns:1.06fr 1fr}}
.collage{transform:rotate(-.35deg);gap:16px;align-items:stretch}
.collage .sm:first-of-type{transform:translateY(12px) rotate(1.4deg)}
.collage .sm:last-of-type{transform:translateY(-2px) rotate(-1.4deg)}
.collage .big img{aspect-ratio:auto;height:100%;min-height:460px}
.collage .sm img{aspect-ratio:auto;height:100%;min-height:150px}
@media(max-width:900px){.collage .big img{min-height:0;aspect-ratio:3/4}
  .collage .sm img{min-height:0;aspect-ratio:4/3}}

/* ---- Tighter, more even section rhythm ---- */
.section{padding-top:clamp(52px,7vw,94px);padding-bottom:clamp(52px,7vw,94px)}
.shead{margin-bottom:2px}
.spec-grid,.cs-grid,.ev-grid,.state-grid,.steps,.more-grid{margin-top:clamp(32px,4vw,46px)}
.essence.section{padding-top:clamp(50px,6vw,84px);padding-bottom:clamp(50px,6vw,84px)}
.essence p{margin-top:6px}

/* ---- CONTACT SHEET: 8-tile editorial mosaic (no gaps) ---- */
.cs-grid{grid-template-columns:repeat(6,1fr);grid-auto-rows:170px;gap:16px}
.cs{grid-row:span 2}
.t1{grid-column:span 2}.t2{grid-column:span 4}
.t3{grid-column:span 4}.t4{grid-column:span 2}
.t5{grid-column:span 3}.t6{grid-column:span 3}
.t7{grid-column:span 2}.t8{grid-column:span 4}
@media(max-width:820px){.cs-grid{grid-template-columns:repeat(2,1fr);grid-auto-rows:150px}
  .t1,.t2,.t3,.t4,.t5,.t6,.t7,.t8{grid-column:span 1;grid-row:span 2}}
@media(max-width:460px){.cs-grid{grid-template-columns:1fr}}

/* ---- Specialist cards: even heights ---- */
.spec-copy{min-height:150px}
@media(max-width:900px){.spec-copy{min-height:0}}

/* ---- Keep the image "Add your photo" chips from feeling flat: subtle frame ---- */
.spec-media,.state-media,.mcard-media,.collage .big,.collage .sm,.cs,.ev,.about-media img{background:#0e1120}



.strip{background:linear-gradient(180deg,#FFFFFF 0%,#F5F8FF 100%)!important;color:var(--ink)!important;padding:clamp(42px,5vw,66px) 0 clamp(50px,6vw,74px)!important}
.strip .wrap{padding-top:0;padding-bottom:0}
.strip-grid{gap:16px}
.svc{background:#fff!important;color:#161a29!important;border:1px solid rgba(20,30,60,.09)!important;border-radius:20px!important;
  padding:26px 24px 24px!important;min-height:176px!important;box-shadow:0 10px 26px rgba(24,34,70,.06)!important;
  overflow:hidden;isolation:isolate}
.svc::before{content:""!important;position:absolute!important;top:0!important;left:0!important;right:0!important;bottom:auto!important;
  width:auto!important;height:4px!important;border:0!important;border-radius:0!important;
  background:var(--acc,#3358E0)!important;opacity:.95;z-index:1}
.svc::after{display:none!important}
.svc .si{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;
  background:var(--chip,#EDF1FF)!important;color:var(--acc,#3358E0)!important}
.svc .si svg{width:24px;height:24px}
.svc b{color:#161a29!important;font-family:var(--serif);font-weight:700;font-size:1.3rem;letter-spacing:.2px}
.svc span{color:#59607200!important;color:#5a6072!important;font-size:.86rem;line-height:1.5}
.svc .go{color:var(--acc,#3358E0)!important;margin-top:auto;font-size:.68rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase}
.svc:hover{background:#fff!important;transform:translateY(-6px)!important;box-shadow:0 24px 48px rgba(24,34,70,.13)!important}
.svc:nth-child(1){--acc:#3358E0;--chip:#EBF0FF}
.svc:nth-child(2){--acc:#7A50EC;--chip:#F1ECFE}
.svc:nth-child(3){--acc:#E24C74;--chip:#FDECF1}
.svc:nth-child(4){--acc:#C07E10;--chip:#FBF2DC}
.svc:nth-child(5){--acc:#0E9E90;--chip:#E6F7F3}
.svc:nth-child(6){--acc:#2E3552;--chip:#EDEFF6}
.svc:nth-child(4) .si,.svc:nth-child(4) .go{color:var(--acc)!important}
@media(max-width:640px){.svc{min-height:150px!important;padding:22px 20px!important}}

.svc.svc-img{background:none!important;color:#fff!important;border:0!important;isolation:isolate;min-height:212px!important;justify-content:flex-end!important;padding:24px 22px!important}
.svc.svc-img::before{display:none!important}
.svc-bg{position:absolute!important;inset:0;z-index:-2;border-radius:20px;overflow:hidden}
.svc-bg img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s ease}
.svc.svc-img:hover .svc-bg img{transform:scale(1.06)}
.svc.svc-img::after{content:"";position:absolute;inset:0;z-index:-1;border-radius:20px;background:linear-gradient(180deg,rgba(5,8,20,.06) 0%,rgba(5,8,20,.20) 28%,rgba(5,8,20,.50) 48%,rgba(5,8,20,.80) 68%,rgba(5,8,20,.94) 100%)}
.svc.svc-img .si{background:rgba(8,10,20,.42)!important;border:1px solid rgba(255,255,255,.16)!important;color:#fff!important}
.svc.svc-img b{color:#fff!important;text-shadow:0 1px 10px rgba(5,8,20,.55)}
.svc.svc-img span{color:rgba(255,255,255,.96)!important;text-shadow:0 1px 8px rgba(5,8,20,.5)}
.svc.svc-img .go{color:#fff!important;text-shadow:0 1px 8px rgba(5,8,20,.5)}
.svc.svc-img .svc-copy{display:flex;flex-direction:column;gap:6px;align-self:flex-start;position:relative;z-index:1;max-width:100%;margin:0 -4px -2px;padding:12px 15px 13px;border-radius:13px;background:linear-gradient(100deg,rgba(5,8,20,.9) 0%,rgba(5,8,20,.76) 60%,rgba(5,8,20,.24) 100%);backdrop-filter:blur(2px)}
.svc.svc-img .svc-copy .go{margin-top:4px}
.svc.svc-img .svc-copy b,.svc.svc-img .svc-copy span{text-shadow:0 1px 6px rgba(5,8,20,.45)}
.svc.svc-cta{background:linear-gradient(135deg,#0B1030,#1B2140 55%,#2A356E)!important;color:#fff!important;border:0!important;min-height:212px!important;justify-content:flex-end!important}
.svc.svc-cta::before{background:var(--amber)!important}
.svc.svc-cta .si{background:rgba(255,255,255,.14)!important;color:#FFD36A!important}
.svc.svc-cta b{color:#fff!important}
.svc.svc-cta span{color:rgba(255,255,255,.82)!important}
.svc.svc-cta .go{color:#FFD36A!important}



#enquiry [hidden]{display:none!important}
#enquiry .msform{position:relative}
#enquiry .ms-prog{margin:2px 0 20px}
#enquiry .ms-prog-top{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:8px}
#enquiry .ms-step-label{font-family:var(--sans);font-size:.74rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--cobalt)}
#enquiry .ms-step-label b{color:var(--cobalt)}
#enquiry .ms-step-name{font-family:var(--sans);font-size:.8rem;font-weight:600;color:var(--muted)}
#enquiry .ms-bar{height:6px;border-radius:6px;background:var(--stone);overflow:hidden}
#enquiry .ms-bar i{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,var(--cobalt),var(--violet,#8057F5));transition:width .35s ease}
#enquiry .ms-step{display:none;animation:msfade .3s ease}
#enquiry .ms-step.is-active{display:block}
@keyframes msfade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
#enquiry .ms-h{font-family:var(--serif,Playfair Display,serif);font-size:1.35rem;margin:0 0 4px;color:var(--ink)}
#enquiry .ms-sub{font-family:var(--sans);font-size:.9rem;color:var(--muted);margin:0 0 16px}
#enquiry .ms-multi{font-weight:500;font-size:.72rem;text-transform:none;letter-spacing:0;color:var(--muted);margin-left:6px}
#enquiry .ms-cards{display:grid;grid-template-columns:1fr 1fr;gap:10px}
#enquiry .ms-cards.one{grid-template-columns:1fr}
#enquiry .ms-card{display:block;position:relative;border:1.5px solid var(--line);border-radius:12px;padding:12px 13px 12px 40px;cursor:pointer;background:var(--paper);transition:.18s}
#enquiry .ms-card:hover{border-color:var(--cobalt)}
#enquiry .ms-card input{position:absolute;left:13px;top:14px;width:17px;height:17px;accent-color:var(--cobalt);margin:0}
#enquiry .ms-card .ms-card-t{display:block;font-family:var(--sans);font-weight:700;font-size:.86rem;color:var(--ink)}
#enquiry .ms-card .ms-card-d{display:block;font-family:var(--sans);font-size:.76rem;line-height:1.45;color:var(--muted);margin-top:3px}
#enquiry .ms-card.is-on{border-color:var(--cobalt);background:var(--sky,#EAF1FF)}
#enquiry .ms-nav{display:flex;gap:12px;align-items:center;margin-top:22px}
#enquiry .ms-nav .btn{cursor:pointer}
#enquiry .ms-prev{background:transparent;border:1.5px solid var(--line);color:var(--ink)}
#enquiry .ms-prev:hover{border-color:var(--ink)}
#enquiry .ms-next,#enquiry .ms-submit{margin-left:auto}
#enquiry .ms-err{border-color:var(--clay)!important;box-shadow:0 0 0 3px rgba(255,70,103,.14)}
#enquiry .ms-errmsg{color:var(--clay);font-size:.78rem;font-family:var(--sans);margin:6px 0 0;display:none}
#enquiry .ms-errmsg.show{display:block}
#enquiry .ms-files{margin-top:10px;display:flex;flex-wrap:wrap;gap:10px}
#enquiry .ms-thumb{position:relative;width:74px;height:74px;border-radius:10px;overflow:hidden;border:1px solid var(--line)}
#enquiry .ms-thumb img{width:100%;height:100%;object-fit:cover;display:block}
#enquiry .ms-thumb button{position:absolute;top:2px;right:2px;width:20px;height:20px;border:none;border-radius:50%;background:rgba(9,13,24,.78);color:#fff;font-size:13px;line-height:20px;cursor:pointer;padding:0}
#enquiry .ms-agree{font-family:var(--sans);font-size:.76rem;color:var(--muted);line-height:1.5;background:var(--sky,#EAF1FF);border-radius:12px;padding:12px 14px;margin:18px 0 4px}
#enquiry .ms-agree ul{margin:6px 0 0;padding-left:18px}
#enquiry .ms-agree li{margin:2px 0}
#enquiry .ms-help{font-family:var(--sans);font-size:.75rem;color:var(--muted);margin:6px 0 0}
#enquiry .ms-done{text-align:center;padding:24px 8px}
#enquiry .ms-done h3{font-family:var(--serif,Playfair Display,serif);color:var(--ink);font-size:1.5rem;margin:0 0 8px}
#enquiry .ms-done p{color:var(--muted);font-family:var(--sans);max-width:44ch;margin:0 auto}
#enquiry .ms-done svg{width:52px;height:52px;color:var(--teal,#0CA899);margin-bottom:10px}
@media(max-width:560px){#enquiry .ms-cards{grid-template-columns:1fr}#enquiry .ms-nav{flex-wrap:wrap}#enquiry .ms-next,#enquiry .ms-submit,#enquiry .ms-prev{width:100%;margin-left:0}#enquiry .ms-prog-top{flex-direction:column;gap:2px}}
